#!/usr/bin/env node
/* Books-2 ophthalmology wave 1: Parsons' Diseases of the Eye 23rd, Section IV (Ch 11-16)
 * and Section VI (Ch 23 lids, Ch 25 orbit) topic map, text chunks in /tmp/books2-work/parson/.
 * Facts rewritten in own words; no verbatim copy of sentences, tables or figures. New MCQs only. */
import fs from "node:fs";
import path from "node:path";
import { createRequire } from "node:module";
import { fileURLToPath } from "node:url";
const require = createRequire(import.meta.url);
const LP = require("../prep-lessons.js");
const ROOT = path.join(path.dirname(fileURLToPath(import.meta.url)), "..");
const REF = "Parsons' Diseases of the Eye 23rd Edition (topic map; text rewritten, no verbatim copy)";
function mcq(id, q, o, a, exp, r, kp) { return { id, q, o, a, exp, r, kp }; }
function step(tx, say, vis) { return vis ? { tx, say, vis } : { tx, say, vis: null }; }
function tbl(cols, rows) { return { kind: "table", cols, rows }; }
const M = [];
function add(id, title, kb, kbName, aliases, steps, pearls, patho, diffs, invs, mcqs) { M.push({ id, title, kb, kbName, aliases, steps, pearls, patho, diffs, invs, mcqs }); }

add("oph-lids", "Diseases of the eyelids", "eyelid_disorders_blepharitis_chalazion", "Diseases of the Eyelids",
 ["Blepharitis", "Stye and chalazion", "Entropion and ectropion", "Ptosis and lid tumours"],
 [step("**Blepharitis** inflames lid margins in anterior (staphylococcal ulcerative with collarettes and madarosis, or seborrhoeic squamous with greasy scales) and posterior (meibomian gland dysfunction with capped orifices and frothy tears) patterns. Chronicity breeds styes, chalazia, marginal keratitis and dry eye. Management is lid hygiene first (warm compresses melting meibum, scrubs, massage), short topical antibiotics for infective flares, and systemic doxycycline or azithromycin for posterior disease with rosacea. Demodex mites (cylindrical dandruff at lash bases) need tea tree based lid care.", "Crusty lashes need heat and scrubs before antibiotics. Frothy tears and capped oil glands mean posterior disease."),
  step("Gland lumps separate by pain and wall: **hordeolum externum (stye)** is an acute painful staphylococcal abscess of lash follicle or Zeiss gland pointing at the margin, while **hordeolum internum** strikes meibomian glands pointing inward; both get heat and usually drain spontaneously, with incision only for pointing persistence. **Chalazion** is a chronic painless sterile lipogranuloma of blocked meibomian gland (firm tarsal nodule, conjunctival granuloma inside), treated conservatively, then steroid injection or incision and curettage through conjunctiva. Recurrent or atypical chalazion in older adults needs histology to exclude sebaceous carcinoma masquerade.", "Painful margin lump is stye; painless tarsal lump is chalazion. Recurrent chalazion in elderly earns a biopsy."),
  step("Lid malpositions threaten cornea by exposure or lash trauma: **entropion** turns the margin inward (involutional from horizontal laxity and retractor disinsertion, cicatricial from trachoma or burns, spastic after surgery, congenital), while **ectropion** everts it (involutional medial ectropion with punctal eversion and watering, paralytic from facial palsy, cicatricial). Trichiasis (misdirected lashes) and distichiasis (extra posterior row) abrade cornea causing ulcers; epilation is stopgap, with electrolysis, cryotherapy or lid surgery definitive. Facial palsy lagoons the eye, needing taping, lubricants and often gold weight or tarsorrhaphy.", "Lashes touching cornea ulcerate it. Palsy that cannot close the eye needs taping and weights, not waiting."),
  step("**Ptosis** droops the upper lid (margin reflex distance under 2 mm): aponeurotic (involutional, high crease, levator function preserved), myogenic (levator weakness), neurogenic (third nerve with down and out eye, Horner with miosis and anhidrosis), mechanical (mass or oedema) and pseudoptosis (phthisis, contralateral retraction). Levator resection suits fair function; frontalis sling bypasses poor function (congenital, Marcus Gunn jaw winking). Commonest lid malignancy is **basal cell carcinoma** (lower lid, pearly rolled edge with telangiectasia), excised with margin control; sebaceous carcinoma mimics recurrent chalazion and demands map biopsies.", "Droop with small pupil and no sweat is Horner. Pearly lower lid ulcer with vessels is basal cell.", tbl(["Lesion", "Gland", "Character"], [["Stye externum", "Zeiss or lash follicle", "Acute painful, points outward"], ["Stye internum", "Meibomian", "Painful, points inward"], ["Chalazion", "Meibomian blocked", "Chronic painless nodule"], ["Sebaceous carcinoma", "Meibomian malignant", "Recurrent atypical chalazion"]]))],
 ["Hygiene before antibiotics in blepharitis", "Stye hurts, chalazion does not", "Lash cornea touch means ulcer risk", "Recurrent chalazion in elderly: biopsy"],
 "Meibomian inspissation stagnates lipid, inviting bacterial lipases that saponify tears into irritants, while involutional canthal laxity and retractor dehiscence rotate lax lids and chronic tarsal scarring contracts posterior lamella inward.",
 ["Stye versus chalazion by pain and course", "Entropion versus ectropion by margin direction", "Basal cell versus sebaceous carcinoma by age and behaviour"],
 ["Slit lamp margin and meibomian assessment", "Corneal staining for lash or exposure damage", "Biopsy of atypical or recurrent lid lesions"],
 [mcq("bk2-oph-001", "Posterior blepharitis is distinguished from anterior disease chiefly by which findings?", ["Greasy lash scales only", "Capped meibomian orifices, turbid expressed meibum and frothy tears", "Lid ulcers always", "No tear abnormality"], 1, "Posterior disease is meibomian gland dysfunction with altered lipid layer causing evaporative dry eye; anterior disease crusts lashes (staphylococcal collarettes or seborrhoeic scales). Management targets glands with heat, massage and systemic tetracyclines.", ["Incorrect. Scales mark anterior seborrhoeic disease.", "Correct. Meibomian capping and frothy tears.", "Incorrect. Ulceration is staphylococcal anterior.", "Incorrect. Tear film destabilises in posterior disease."], "Frothy tears, capped oil holes: posterior blepharitis."),
  mcq("bk2-oph-002", "Painful acute swelling at the lid margin pointing outward with a lash at its apex is what and first treatment?", ["Chalazion; excise urgently", "Hordeolum externum (stye); warm compresses, usually self draining", "Basal cell carcinoma; wide excision", "Xanthelasma; lipid lowering"], 1, "Stye is an acute staphylococcal abscess of anterior glands; heat localises it and most rupture outward, antibiotics reserved for spreading cellulitis. Chalazion is chronic and painless.", ["Incorrect. Chalazion is painless and chronic.", "Correct. Stye, heat first.", "Incorrect. Cancer grows slowly without acute pain.", "Incorrect. Xanthelasma is painless lipid plaque."], "Hurts at the lash line: stye, heat it."),
  mcq("bk2-oph-003", "Firm painless tarsal nodule present 3 months with conjunctival granuloma on eversion most likely is what?", ["Stye", "Chalazion (lipogranuloma of blocked meibomian gland)", "Preseptal cellulitis", "Dacryocystitis"], 1, "Chalazion is sterile chronic granulomatous retention, managed conservatively then steroid injection or conjunctival incision and curettage; styes are acute and painful.", ["Incorrect. Styes ache acutely.", "Correct. Chronic chalazion.", "Incorrect. Cellulitis reddens and swells diffusely.", "Incorrect. Tear sac sits medially below canthus."], "Painless months old lid lump: chalazion."),
  mcq("bk2-oph-004", "Recurrent chalazion-like lesion in a 70 year old with loss of lashes should prompt exclusion of what?", ["Viral wart", "Sebaceous carcinoma masquerading as chalazion", "Allergy", "Dry eye"], 1, "Elderly meibomian malignancy mimics benign lumps, destroys lashes (madarosis), and needs full thickness biopsy with map sampling for pagetoid spread; repeated curettage without histology delays diagnosis.", ["Incorrect. Warts are papillomatous, not tarsal.", "Correct. Sebaceous carcinoma masquerade.", "Incorrect. Allergy itches bilaterally.", "Incorrect. Dry eye lacks nodules."], "Old lid lump that returns: rule out sebaceous cancer."),
  mcq("bk2-oph-005", "Involutional entropion is best corrected by addressing which mechanism?", ["Excess skin only", "Horizontal lid laxity with lower retractor disinsertion (tightening plus retractor repair)", "Levator resection", "Tarsorrhaphy always"], 1, "Ageing stretches canthal tendons and dehisces retractors, rotating the margin inward; lateral tarsal strip with retractor reinsertion restores tension. Skin excision alone recurs.", ["Incorrect. Skin is secondary.", "Correct. Tighten lid, reattach retractors.", "Incorrect. Levator lifts ptosis, not entropion.", "Incorrect. Tarsorrhaphy narrows aperture for exposure."], "Lax lid rolling in: tighten and reattach."),
  mcq("bk2-oph-006", "Medial ectropion with watering in an elderly patient is explained and initially managed how?", ["Punctal eversion from lid laxity; lubricants then medial spindle or lid tightening surgery", "Blocked duct; dacryocystorhinostomy at once", "Glaucoma; drops", "Uveitis; steroids"], 1, "Lax lower lid everts the punctum from the tear lake, spilling tears (epiphora); surgery repositions punctum and tensions lid. Duct obstruction instead shows mucopurulent regurgitation on sac pressure.", ["Correct. Lax punctum spills tears.", "Incorrect. No sac mucocele here.", "Incorrect. Pressure is unrelated.", "Incorrect. No anterior chamber cells."], "Lax lid spills tears: reposition the punctum."),
  mcq("bk2-oph-007", "Bell palsy with incomplete closure threatens the eye chiefly through what and needs which protection?", ["Optic neuritis; steroids", "Exposure keratopathy; frequent lubricants, taping and moisture chamber", "Retinal detachment; laser", "Cataract; early surgery"], 1, "Lagoons cornea dries and ulcerates, especially overnight; aggressive lubrication with lid taping bridges recovery, with gold weights or tarsorrhaphy for prolonged palsy.", ["Incorrect. Optic nerve is uninvolved.", "Correct. Exposure needs taping and drops.", "Incorrect. Retina is posterior.", "Incorrect. Lens opacifies slowly."], "Eye that cannot shut must be taped shut."),
  mcq("bk2-oph-008", "Commonest malignant eyelid tumour and its classic site and sign are what?", ["Squamous cell upper lid", "Basal cell carcinoma of lower lid with pearly rolled edge and telangiectasia", "Melanoma of brow", "Retinoblastoma of margin"], 1, "Sun driven basal cell favours lower lid and medial canthus, ulcerating centrally (rodent ulcer) while sparing lashes early; excision with margin control cures most. Medial canthal lesions threaten lacrimal invasion.", ["Incorrect. Squamous is second commonest.", "Correct. Lower lid pearly ulcer.", "Incorrect. Melanoma is rarer and pigmented.", "Incorrect. Retinoblastoma is intraocular childhood."], "Pearly lower lid sore that never heals: basal cell."),
  mcq("bk2-oph-009", "Trichiasis threatens vision by which mechanism and definitive options?", ["Raised pressure; drops", "Misdirected lashes abrading cornea causing ulcers; epilation stopgap with electrolysis, cryo or surgery", "Retinal traction; vitrectomy", "Lens dislocation; lensectomy"], 1, "Lash cornea touch (trachomatous, involutional or traumatic) erodes epithelium inviting bacterial ulcers and scarring; removing or redirecting follicles protects sight.", ["Incorrect. Pressure is glaucoma.", "Correct. Lash abrasion needs follicle ablation.", "Incorrect. Retina is posterior segment.", "Incorrect. Lens sits behind iris."], "Lashes scraping cornea: ablate the follicles."),
  mcq("bk2-oph-010", "Ptosis with miosis, anhidrosis and apparent enophthalmos localises to which pathway?", ["Third nerve", "Sympathetic chain (Horner syndrome)", "Seventh nerve", "Myasthenia always"], 1, "Oculosympathetic loss droops Muller muscle mildly, constricts pupil and dries ipsilateral face; third nerve ptosis is complete with down and out eye and dilated pupil.", ["Incorrect. Third nerve dilates pupil.", "Correct. Horner triad plus anhidrosis.", "Incorrect. Seventh closes, not opens.", "Incorrect. Myasthenia fatigues variably."], "Droop plus tiny pupil plus dry cheek: Horner.")]);

add("oph-orbit", "Diseases of the orbit", "orbital_disease_proptosis_thyroid", "Diseases of the Orbit",
 ["Proptosis workup", "Thyroid eye disease", "Orbital cellulitis", "Cavernous sinus thrombosis"],
 [step("**Proptosis** (exophthalmos over 21 mm or asymmetry over 2 mm on Hertel) demands direction, duration and vision: axial proptosis points intraconal (optic nerve glioma, haemangioma), eccentric displacement points extraconal (lacrimal tumours superotemporal, mucoceles from sinuses, metastases). Red flags are pain, diplopia, vision loss, pulsation, bruit and systemic features. Workup pairs contrast CT or MRI (muscles, apex, sinuses, bone) with thyroid function, blood counts and biopsy of accessible lesions; cavernous haemangioma is the commonest benign adult orbital tumour.", "Measure it, watch which way it pushes, scan the apex. Axial means inside the muscle cone."),
  step("**Thyroid eye disease** (Graves orbitopathy) is the commonest proptosis cause overall: autoimmune fibroblast activation swells extraocular muscles (tendon sparing enlargement, inferior then medial rectus) and fat, giving lid retraction with lag, lid lag on downgaze (von Graefe), staring appearance, restrictive myopathy and compressive optic neuropathy at the apex. Activity scores (CAS) separate active (steroids, rituximab patterns, orbital radiotherapy) from burnt out fibrotic disease (strabismus then lid surgery, decompression for neuropathy or disfigurement). Smoking worsens and radioiodine can flare disease.", "Staring lids plus fat muscles sparing tendons: Graves orbit. Active disease gets steroids, quiet disease gets surgery."),
  step("**Orbital cellulitis** breaches the septum from ethmoid sinusitis (children through thin lamina), presenting with fever, painful proptosis, restricted painful eye movements, chemosis and vision threat, versus preseptal cellulitis where globe, movements and vision stay normal. Contrast CT grades Chandler spread (subperiosteal abscess displacing globe); IV broad antibiotics cover sinus flora urgently, with drainage for abscess, optic compromise or intracranial extension. Cavernous sinus thrombosis bilateralises chemosis with ophthalmoplegia, trigeminal signs and sepsis, needing MRI venography and anticoagulation debates in ICU care.", "Painful eye that cannot move with fever is post septal until scanned. Bilateral red frozen eyes mean cavernous sinus."),
  step("Vascular and malignant patterns complete the orbit: carotid cavernous fistula gives pulsatile proptosis with bruit and arterialised conjunctival vessels after trauma (direct) or spontaneously (indirect dural); retinoblastoma and rhabdomyosarcoma dominate childhood malignancy (rapid superonasal mass in rhabdomyosarcoma needing urgent biopsy and chemoradiation); adult metastases (breast, lung, prostate) and lymphoma (salmon patch, moulding without bony destruction) infiltrate insidiously. Optic nerve sheath meningioma shows tram track calcification with progressive vision loss.", "Pulsing eye with whoosh is fistula. Child with overnight ballooning upper lid mass: rhabdomyosarcoma.", tbl(["Sign", "Disease", "Anchor"], [["Lid retraction and lag", "Thyroid eye disease", "Tendon sparing muscles"], ["Painful frozen eye, fever", "Orbital cellulitis", "Post septal, sinus source"], ["Bilateral chemosis, sepsis", "Cavernous thrombosis", "Cross midline venous spread"], ["Pulsation and bruit", "Carotid cavernous fistula", "Arterialised conjunctiva"]]))],
 ["Measure proptosis, note direction", "Thyroid disease spares muscle tendons", "Septum divides preseptal from orbital", "Bilateralise means cavernous sinus"],
 "Glycosaminoglycan deposition expands orbital fat and muscle bellies within a rigid bony box, raising intraorbital pressure toward the apex where the optic nerve strangulates; valveless ophthalmic veins conduct sinus infection posteriorly to both cavernous sinuses.",
 ["Preseptal versus orbital cellulitis by globe and vision", "Thyroid myopathy versus myasthenia by fatigability and antibodies", "Cellulitis versus pseudotumour by fever and sinus disease"],
 ["Hertel exophthalmometry and motility charting", "Contrast CT or MRI orbit with sinuses and apex", "Thyroid function, counts, and lesion biopsy"],
 [mcq("bk2-oph-011", "Axial versus eccentric proptosis localises lesions how?", ["No meaning", "Axial suggests intraconal mass; eccentric displacement points extraconal toward opposite side", "Axial always thyroid", "Eccentric always benign"], 1, "Muscle cone geometry pushes straight forward when filled from inside and deviates the globe away from outside masses; imaging then hunts glioma or haemangioma versus lacrimal, sinus or metastatic lesions.", ["Incorrect. Direction localises strongly.", "Correct. Axial intraconal, eccentric extraconal.", "Incorrect. Thyroid enlarges muscles, often asymmetric.", "Incorrect. Malignancy displaces too."], "Straight out means inside cone; pushed aside means outside."),
  mcq("bk2-oph-012", "Thyroid eye muscle enlargement spares which structure, distinguishing it from myositis?", ["Muscle belly", "Tendon of insertion", "Optic nerve", "Fat"], 1, "Graves swells bellies leaving tendons thin on imaging, while idiopathic orbital myositis inflames tendon to sclera with severe pain. This tendon rule guides steroids versus thyroid pathways.", ["Incorrect. Bellies swell markedly.", "Correct. Tendons spared in thyroid.", "Incorrect. Nerve compresses at apex late.", "Incorrect. Fat expands too."], "Fat bellies, skinny tendons: thyroid eye."),
  mcq("bk2-oph-013", "Active versus burnt out thyroid eye disease management differs how?", ["Always surgery first", "Active inflammation gets immunotherapy (steroids); fibrotic quiet disease gets rehabilitative surgery", "Never treat", "Radiotherapy for all"], 1, "Clinical activity scores separate immunosuppression responsive congestion from stable fibrosis needing staged decompression, strabismus and lid repair; operating on hot disease recurs.", ["Incorrect. Hot orbits scar worse operated.", "Correct. Cool inflammation first, cut when quiet.", "Incorrect. Neuropathy blinds untreated.", "Incorrect. Radiotherapy selected actives only."], "Hot eye gets steroids; cold eye gets surgery."),
  mcq("bk2-oph-014", "Child with ethmoid sinusitis, fever, proptosis and painful restricted movements needs what?", ["Oral antihistamine", "Urgent contrast CT with IV antibiotics for orbital cellulitis", "Warm compress alone", "Patch and review weeks"], 1, "Post septal infection threatens vision and brain through lamina and venous spread; imaging grades abscess needing drainage while antibiotics cover sinus flora. Preseptal disease spares globe function.", ["Incorrect. Allergy lacks fever and ophthalmoplegia.", "Correct. Scan and IV treat orbital cellulitis.", "Incorrect. Compress cannot reach orbit.", "Incorrect. Delay risks blindness."], "Fever plus frozen proptosed eye: scan and drip."),
  mcq("bk2-oph-015", "Bilateral chemosis, ophthalmoplegia and sepsis after sinusitis indicate which emergency?", ["Conjunctivitis", "Cavernous sinus thrombosis", "Dry eye", "Episcleritis"], 1, "Intercavernous connections bilateralise ophthalmic venous congestion with cranial nerve palsies and trigeminal pain; MRI venography confirms and ICU level anticoagulation and antibiotics follow.", ["Incorrect. Conjunctivitis spares movements.", "Correct. Cavernous sinus thrombosis.", "Incorrect. Dry eye lacks swelling and sepsis.", "Incorrect. Episcleritis is sectoral and benign."], "Both eyes swollen shut with sepsis: cavernous clot."),
  mcq("bk2-oph-016", "Pulsatile proptosis with bruit and corkscrew conjunctival vessels after head trauma suggests what?", ["Thyroid eye disease", "Direct carotid cavernous fistula", "Orbital cellulitis", "Mucocele"], 1, "Internal carotid tear into cavernous sinus arterialises ophthalmic veins, engorging eyes with audible bruit and raised episcleral pressure causing secondary glaucoma; angiography with embolisation treats.", ["Incorrect. Thyroid lacks bruit and pulsation.", "Correct. Traumatic carotid cavernous fistula.", "Incorrect. Cellulitis is febrile and painful.", "Incorrect. Mucoceles expand silently."], "Whooshing pulsing eye after trauma: fistula."),
  mcq("bk2-oph-017", "Rapidly progressive superonasal orbital mass in a 6 year old most concerning for what?", ["Dermoid cyst", "Rhabdomyosarcoma needing urgent biopsy and chemoradiation", "Chalazion", "Thyroid disease"], 1, "Paediatric embryonal sarcoma balloons within days with ptosis and displacement; delay metastasises, while prompt tissue with multimodal therapy saves life and often the eye.", ["Incorrect. Dermoids grow slowly since birth.", "Correct. Rhabdomyosarcoma emergency.", "Incorrect. Chalazion is tarsal and small.", "Incorrect. Thyroid orbitopathy is adult."], "Child orbit exploding in days: sarcoma until biopsied."),
  mcq("bk2-oph-018", "Optic nerve sheath meningioma imaging hallmark with slowly progressive vision loss is what?", ["Tendon sparing muscles", "Tram track calcification around the nerve", "Bone destruction", "Ring enhancing lesion"], 1, "Dural calcification rails the nerve on CT with optociliary shunts on fundus; surgery blinds, so observation or fractionated radiotherapy suits most, reserving excision for blind painful eyes.", ["Incorrect. Tendons belong to thyroid.", "Correct. Tram track meningioma.", "Incorrect. Destruction suggests metastasis.", "Incorrect. Rings suggest abscess."], "Rails around nerve with fading vision: sheath meningioma."),
  mcq("bk2-oph-019", "Orbital lymphoma is distinguished from idiopathic inflammation and cellulitis chiefly by what?", ["Fever always", "Painless salmon moulding mass without bony destruction in older adult", "Rapid pain", " Sinus pus"], 1, "Low grade marginal zone lymphoma moulds to globe and bone painlessly over months; biopsy with immunophenotyping directs radiation with excellent control. Pain and fever favour inflammation or infection.", ["Incorrect. Lymphoma is typically afebrile.", "Correct. Painless moulding salmon lesion.", "Incorrect. Pain marks pseudotumour.", "Incorrect. Pus marks sinusitis spread."], "Quiet pink orbital mass in elderly: lymphoma."),
  mcq("bk2-oph-020", "Compressive optic neuropathy in thyroid eye disease occurs at which site and needs what?", ["Cornea; transplant", "Orbital apex crowding; urgent steroids or decompression for dyschromatopsia and field loss", "Lens; cataract surgery", "Macula; injection"], 1, "Apical muscle crowding strangles nerve function (colour desaturation, afferent pupil defect, field constriction) despite a white quiet eye; vision rescue cannot await rehabilitative staging.", ["Incorrect. Cornea stays clear.", "Correct. Apex compression, decompress urgently.", "Incorrect. Lens is anterior.", "Incorrect. Macula injections treat AMD."], "Quiet staring eye losing colour vision: apex squeeze.")]);

add("oph-conjunctiva", "Diseases of the conjunctiva", "conjunctivitis_trachoma_allergic", "Diseases of the Conjunctiva",
 ["Bacterial and viral conjunctivitis", "Trachoma and SAFE", "Allergic and vernal disease", "Pterygium and dry eye"],
 [step("**Acute bacterial conjunctivitis** glues lids with mucopurulent discharge (staphylococcal, streptococcal, Haemophilus in children), while **viral disease** (adenovirus) waters with follicles, preauricular nodes, recent upper respiratory contact and cross infectivity; membranes or pseudomembranes mark severe adenoviral or streptococcal variants. Gonococcal conjunctivitis is hyperacute with copious pus and corneal perforation risk in neonates and adults, needing systemic ceftriaxone plus lavage. Chlamydial inclusion conjunctivitis causes chronic follicular disease with mucopurulent discharge in sexually active adults (treat partners with azithromycin).", "Pus that glues is bacterial; water with nodes is viral. Hyperacute pus that melts cornea is gonococcus: inject ceftriaxone."),
  step("**Trachoma** (Chlamydia trachomatis serotypes A to C) blinds through repeated childhood infection scarring lids inward: McCallan stages run follicular activity to cicatricial quiet, while WHO FISTO grades follicles, intense inflammation, scarring, trichiasis and corneal opacity. Diagnosis needs upper tarsal follicles with pannus, Herbert pits or stellate scarring. The **SAFE** strategy (surgery for trichiasis, antibiotics with single dose azithromycin, facial cleanliness, environmental improvement) eliminates blinding disease; trichiasis surgery (bilamellar tarsal rotation) precedes corneal opacity.", "Upper lid follicles plus pannus is trachoma. SAFE with azithromycin stops villages going blind."),
  step("**Allergic conjunctivitis** itches with ropy discharge and papillae: seasonal hay fever type, perennial dust mite type, and **vernal keratoconjunctivitis** in atopic boys with giant cobblestone papillae, Trantas dots and shield ulcers threatening vision. Management avoids rubbing, cools with lubricants, mast cell stabilisers and antihistamines, reserving short steroids or ciclosporin and supratarsal injections for shield disease. Atopic keratoconjunctivitis scars lids chronically. Contact lens overwear breeds giant papillary conjunctivitis with mucus and lens intolerance, eased by lens holiday and fit change.", "Itch dominates allergy; giant papillae in atopic boys is vernal. Shield ulcer in vernal disease threatens sight."),
  step("Degenerative and surface disease: **pinguecula** is a benign yellow nasal nodule that never crosses limbus, while **pterygium** is a wing shaped growth invading cornea (UV driven), needing excision with autograft when encroaching. **Dry eye** burns with fluctuating vision, low tear breakup time and punctate staining, managed by preservative free tears, punctal plugs and ciclosporin; Sjogren, Stevens Johnson and chemical burns need specialist care. Bitot spots (foamy patches) flag vitamin A deficiency in malnourished children.", "Pinguecula stops at limbus, pterygium flies onto cornea. Foamy Bitot spots mean vitamin A deficiency.", tbl(["Discharge", "Disease", "Clue"], [["Mucopurulent gluing", "Bacterial", "No nodes usually"], ["Watery with nodes", "Viral adenovirus", "Highly contagious"], ["Ropy with itch", "Allergic", "Papillae, atopy"], ["Chronic follicular adult", "Chlamydial inclusion", "Treat partners"]]))],
 ["Itch means allergy, pus means bacteria", "Trachoma scars upper lids: SAFE it", "Vernal shield ulcers threaten vision", "Pterygium crosses limbus, pinguecula does not"],
 "Chlamydial elementary bodies provoke follicular lymphoid hyperplasia with papillary hypertrophy, and repeated healing contracts tarsal conjunctiva, rotating lashes inward to abrade cornea into opacification; UV elastosis degenerates interpalpebral collagen into wing shaped fibrovascular ingrowth.",
 ["Bacterial versus viral by discharge and nodes", "Trachoma versus other follicular disease by upper tarsal scarring", "Pinguecula versus pterygium by limbus crossing"],
 ["Slit lamp with fluorescein and eversion", "Conjunctival swab or chlamydial testing by pattern", "Vitamin A and autoimmune review in surface failure"],
 [mcq("bk2-oph-021", "Watery discharge, follicles, tender preauricular node after a cold points to which conjunctivitis?", ["Bacterial", "Viral adenoviral", "Allergic", "Chemical"], 1, "Adenovirus spreads by hand and fomites with pharyngoconjunctival or keratoconjunctivitis patterns; supportive care with hygiene and isolation protects contacts, antibiotics add nothing.", ["Incorrect. Bacteria glue with pus.", "Correct. Viral with nodes.", "Incorrect. Allergy itches without nodes.", "Incorrect. Chemical burns pain immediately."], "Water plus nodes plus cold: adenovirus."),
  mcq("bk2-oph-022", "Hyperacute copious purulent conjunctivitis with rapid corneal ulceration in a neonate needs what?", ["Reassurance", "Systemic ceftriaxone with saline lavage for gonococcal ophthalmia", "Antihistamine drops", "Patch alone"], 1, "Gonococcus penetrates intact epithelium melting cornea within hours; parenteral third generation cephalosporin with frequent lavage and admission saves the eye. Chlamydial neonatal disease instead needs oral macrolides for pneumonia risk.", ["Incorrect. Hours matter in gonococcus.", "Correct. Ceftriaxone plus lavage.", "Incorrect. Itch is absent.", "Incorrect. Patching incubates infection."], "Gushing pus melting newborn cornea: gonococcus."),
  mcq("bk2-oph-023", "WHO FISTO trachoma grading covers which elements?", ["Refraction only", "Follicles, intense inflammation, scarring, trichiasis and corneal opacity", "Pressure staging", "Lens grades"], 1, "Community grading maps activity (F, I) to blinding sequelae (S, T, O), directing azithromycin distribution versus trichiasis surgery camps. McCallan stages instead track individual disease evolution.", ["Incorrect. Refraction is separate.", "Correct. FISTO five signs.", "Incorrect. Pressure is glaucoma.", "Incorrect. Lens is cataract."], "FISTO grades village trachoma to blindness."),
  mcq("bk2-oph-024", "SAFE strategy for trachoma elimination expands to what?", ["Steroids, antibiotics, fluids, exercise", "Surgery for trichiasis, antibiotics, facial cleanliness, environmental improvement", "Screening all febrile", "Sutures for all"], 1, "Surgery corrects in turned lashes, single dose azithromycin clears chlamydia, clean faces break fly transmission and latrines plus water end re infection; antibiotics alone never sustain elimination.", ["Incorrect. Steroids worsen scarring.", "Correct. SAFE four pillars.", "Incorrect. Fever is unrelated.", "Incorrect. Sutures are one pillar only."], "SAFE villages stop trachoma blindness."),
  mcq("bk2-oph-025", "Atopic boy with giant cobblestone papillae, Trantas dots and shield ulcer has which disease and risk?", ["Bacterial conjunctivitis", "Vernal keratoconjunctivitis with vision threatening corneal plaque", "Dry eye only", "Episcleritis"], 1, "Vernal allergy hypertrophies upper tarsal papillae shedding eosinophilic debris into oval superior ulcers; aggressive anti allergic therapy with steroid or ciclosporin bursts plus supratarsal injection heals plaques before scarring.", ["Incorrect. Bacteria lack giant papillae.", "Correct. Vernal shield disease.", "Incorrect. Dry eye lacks papillae.", "Incorrect. Episcleritis is sectoral redness."], "Cobblestones plus shield ulcer in atopic boy: vernal."),
  mcq("bk2-oph-026", "Wing shaped fibrovascular lesion crossing the nasal limbus onto cornea in an outdoor worker is what?", ["Pinguecula", "Pterygium needing excision with autograft when encroaching", "Dermoid", "Naevus"], 1, "UV elastosis drives pterygium over limbus with astigmatism and visual axis threat; bare sclera excision recurs, conjunctival autograft suppresses return. Pinguecula respects limbus and observes.", ["Incorrect. Pinguecula never crosses limbus.", "Correct. Pterygium, graft the bed.", "Incorrect. Dermoids are congenital inferotemporal.", "Incorrect. Naevi pigment without wings."], "Wing onto cornea in sun worker: pterygium."),
  mcq("bk2-oph-027", "Foamy whitish keratinised patches on bulbar conjunctiva in a malnourished child are what and signal?", ["Pinguecula; benign", "Bitot spots signalling vitamin A deficiency needing urgent replacement", "Pterygium; excise", "Naevus; observe"], 1, "Xerosis keratinises surface with foamy debris; systemic vitamin A rescues night blindness and prevents keratomalacia melt. Measles precipitates deficiency crises in underfed children.", ["Incorrect. Age and nutrition forbid pinguecula.", "Correct. Bitot spots, vitamin A now.", "Incorrect. No wing crosses cornea.", "Incorrect. Naevi pigment differently."], "Foamy conjunctival patches in hungry child: vitamin A."),
  mcq("bk2-oph-028", "Giant papillary conjunctivitis with mucus and contact lens intolerance is managed first how?", ["Stronger steroids forever", "Lens holiday with hygiene and fit or material change", "Immediate transplant", "Antibiotics months"], 1, "Protein deposits and mechanical microtrauma hypertrophy papillae; pausing wear with mast cell stabilisers usually resettles, refitting with daily disposables or rigid designs prevents return.", ["Incorrect. Steroids bridge, not cure.", "Correct. Rest lenses, refit better.", "Incorrect. Cornea is intact.", "Incorrect. Infection is absent."], "Lens related cobblestones: rest the lenses."),
  mcq("bk2-oph-029", "Parinaud oculoglandular syndrome pairs unilateral granulomatous conjunctivitis with what?", ["Bilateral nodes", "Ipsilateral preauricular lymphadenopathy (cat scratch, tularaemia patterns)", "No nodes ever", "Inguinal nodes"], 1, "Conjunctival inoculation of Bartonella or Francisella drains to preauricular nodes; history of cats, rabbits or ticks with serology directs macrolide or aminoglycoside therapy.", ["Incorrect. Disease stays ipsilateral.", "Correct. Preauricular nodes with granuloma.", "Incorrect. Nodes define the syndrome.", "Incorrect. Groin drains legs."], "Granuloma eye plus ear node: Parinaud."),
  mcq("bk2-oph-030", "Chronic follicular conjunctivitis with mucopurulent discharge in a sexually active adult needs which systemic step?", ["Topical steroid alone", "Single dose azithromycin with partner treatment for chlamydial inclusion conjunctivitis", "Surgery", "No treatment"], 1, "Genital chlamydia seeds eyes by hand; genital and ocular therapy with partner notification prevents reinfection and tubal or epididymal complications. Steroids alone prolong shedding.", ["Incorrect. Steroids mask and prolong.", "Correct. Azithromycin plus partners.", "Incorrect. No surgical target.", "Incorrect. Chronicity needs cure."], "Adult follicles plus discharge: treat chlamydia and partners.")]);

add("oph-cornea", "Corneal ulcers and keratitis", "corneal_ulcer_keratitis", "Corneal Ulcers and Keratitis",
 ["Bacterial corneal ulcer", "Fungal and acanthamoeba keratitis", "Viral keratitis", "Perforation and grafting"],
 [step("**Bacterial corneal ulcers** follow epithelial breakdown (trauma, contact lens overwear, dry eye, lid disease) with pain, photophobia, ciliary injection, grey infiltrate and anterior chamber cells; **hypopyon** layers pus inferiorly behind severe ulcers (sterile reactive in most bacterial disease, infected in fungal). Scraping for Gram, KOH and culture precedes fortified antibiotics (cefazolin plus aminoglycoside patterns, fluoroquinolone monotherapy for small peripheral lesions); steroids wait until infection controlled. Contact lens related Pseudomonas melts rapidly with greenish discharge and needs admission.", "Grey spot plus pain plus red eye after lens overwear: scrape then fortify. Pus level in front chamber marks severe ulcer."),
  step("**Fungal ulcers** (vegetative trauma, filamentous Fusarium and Aspergillus) grow dry raised lesions with feathery edges, satellite infiltrates and stubborn hypopyon, needing KOH scraping and natamycin or voriconazole for weeks; steroids worsen them. **Acanthamoeba keratitis** haunts soft lens wearers rinsing lenses in tap water, with excruciating pain out of proportion, radial perineuritis and ring infiltrate, treated with biguanides (PHMB, chlorhexidine) plus diamidines for months. Both masquerade as bacterial disease failing antibiotics, so atypical ulcers need confocal and repeat scraping.", "Plant injury ulcer that ignores antibiotics is fungal until scraped. Agonising lens related ulcer with ring is acanthamoeba."),
  step("**Herpes simplex keratitis** declares dendritic branching ulcers staining with fluorescein (terminal bulbs), typically after febrile illness or steroids, treated with topical aciclovir or oral valaciclovir; stromal disciform disease and neurotrophic melting follow recurrences, needing antivirals plus cautious steroids only with cover. **Herpes zoster ophthalmicus** (Hutchinson nasal tip sign) threatens Hutchinson plus uveitis and postherpetic neuralgia, needing systemic antivirals within 72 hours. Adenoviral keratoconjunctivitis leaves nummular subepithelial infiltrates with glare for months.", "Branching ulcer with bulbs is herpes simplex: aciclovir, never steroid alone. Nasal tip blisters warn the eye is next."),
  step("Descemetocele (transparent bulge to Descemet), perforation with flat chamber and Seidel positive leak, and endophthalmitis are ulcer emergencies needing tissue adhesive, patch graft or therapeutic **keratoplasty**. Optical penetrating keratoplasty replaces full thickness scarred cornea with donor tissue under steroid and rejection vigilance (Khodadoust rejection line, Khodadoust management with intensive steroids); lamellar techniques (DALK, DSEK, DMEK patterns) spare layers for keratoconus or endothelial failure. Corneal blindness needs eye banking with specular screening and short death to preservation time.", "Leaking ulcer with flat chamber grafts urgently. Rejection line on graft endothelium needs steroid rescue.", tbl(["Ulcer", "Clue", "Drug"], [["Bacterial", "Grey infiltrate, hypopyon", "Fortified antibiotics"], ["Fungal", "Feathery, satellites", "Natamycin weeks"], ["Acanthamoeba", "Ring, severe pain", "Biguanides months"], ["Herpetic dendritic", "Terminal bulbs", "Aciclovir"]]))],
 ["Scrape before fortifying antibiotics", "Fungal ulcers are dry with satellites", "Dendritic ulcer means herpes simplex", "Ring infiltrate with pain means acanthamoeba"],
 "Stromal proteases from bacteria and neutrophils liquefy collagen once epithelium breaches, while fungal hyphae track lamellae resisting penetration and acanthamoeba cysts encyst against drugs; hypopyon leukocytes sediment by gravity in the anterior chamber.",
 ["Bacterial versus fungal ulcer by edges and satellites", "Herpetic versus bacterial by dendrites and sensation", "Perforation versus descemetocele by Seidel and chamber depth"],
 ["Corneal scraping with Gram, KOH and culture", "Fluorescein staining and sensation testing", "Confocal microscopy for atypical or cystic disease"],
 [mcq("bk2-oph-031", "Contact lens overwearer with painful grey corneal infiltrate and hypopyon needs what first?", ["Topical steroid alone", "Corneal scraping for stains and culture then fortified antibiotics", "Patch and discharge", "Immediate transplant"], 1, "Microbial keratitis needs organism identification before intensive therapy; steroids alone melt infected corneas and patching incubates Pseudomonas. Small peripheral lesions may start fluoroquinolone monotherapy locally.", ["Incorrect. Steroid melts infection.", "Correct. Scrape then fortify.", "Incorrect. Patching worsens bacterial load.", "Incorrect. Graft follows perforation or scarring."], "Grey lens ulcer with pus level: scrape, then fortify."),
  mcq("bk2-oph-032", "Dry raised ulcer with feathery margins and satellite lesions after vegetative eye injury suggests what?", ["Bacterial ulcer", "Fungal keratitis needing KOH and natamycin", "Viral dendrite", "Sterile melt"], 1, "Filamentous fungi implant with plant matter, resist antibacterials and penetrate deep; prolonged antifungals with debridement cure, steroids contraindicated. Hypopyon here may harbour hyphae.", ["Incorrect. Bacteria suppurate wetly.", "Correct. Fungal feathery satellites.", "Incorrect. Dendrites branch superficially.", "Incorrect. Sterile melts lack infiltrate."], "Plant scratch ulcer ignoring drops: think fungus."),
  mcq("bk2-oph-033", "Soft lens wearer rinsing lenses in tap water with pain far exceeding signs and ring infiltrate most likely has what?", ["Staphylococcal ulcer", "Acanthamoeba keratitis treated with biguanides for months", "Fungal ulcer", "Herpes simplex"], 1, "Acanthamoeba tracks corneal nerves (radial perineuritis) causing agony with modest early signs; cysts resist therapy demanding months of PHMB or chlorhexidine with diamidines and pain control.", ["Incorrect. Bacteria match signs to pain.", "Correct. Acanthamoeba ring disease.", "Incorrect. Fungus follows plant trauma.", "Incorrect. Herpes dendrites differ."], "Tap water lenses plus agony plus ring: acanthamoeba."),
  mcq("bk2-oph-034", "Branching corneal ulcer with terminal bulbs staining fluorescein is diagnostic of what?", ["Bacterial ulcer", "Herpes simplex dendritic keratitis", "Acanthamoeba", "Exposure melt"], 1, "Viral replication tracks epithelium in dendrites; topical or oral antivirals heal while steroids alone elongate ulcers into geographic blight. Reduced sensation and recurrences confirm herpetic habit.", ["Incorrect. Bacteria form round infiltrates.", "Correct. Herpetic dendrite.", "Incorrect. Amoeba rings differ.", "Incorrect. Exposure dries inferiorly."], "Bulbs on branches: herpes simplex."),
  mcq("bk2-oph-035", "Vesicles on the nasal tip in shingles warn of ocular involvement because which nerve is affected?", ["Facial nerve", "Nasociliary branch of ophthalmic division (Hutchinson sign)", "Optic nerve", "Oculomotor"], 1, "Nasal tip shares nasociliary supply with globe; Hutchinson predicts keratitis, uveitis and neuralgia needing urgent systemic antivirals and eye review. Delay risks scarring and chronic pain.", ["Incorrect. Facial moves face.", "Correct. Nasociliary Hutchinson sign.", "Incorrect. Optic carries vision.", "Incorrect. Oculomotor moves globe."], "Nose tip blisters: eye follows via nasociliary."),
  mcq("bk2-oph-036", "Descemetocele differs from perforated ulcer by which bedside findings?", ["No difference", "Transparent herniating Descemet with formed chamber and negative Seidel versus flat chamber with leaking fluorescein", "More pain", "Bilateral always"], 1, "Descemet bulges clear before rupture (impending perforation needing glue or patch graft urgently); perforation shallows the chamber with aqueous leak diluting fluorescein (Seidel). Both are surgical urgencies.", ["Incorrect. Chamber and leak separate them.", "Correct. Bulge formed versus flat leaking.", "Incorrect. Pain varies.", "Incorrect. Disease is unilateral."], "Clear bulge formed chamber: descemetocele about to burst."),
  mcq("bk2-oph-037", "Khodadoust line on a corneal graft with redness and vision drop signifies what and treatment?", ["Healed graft", "Endothelial rejection needing intensive topical and systemic steroids", "Infection always", "Suture allergy"], 1, "Leukocyte line marches on endothelium in immune rejection; hourly steroids rescue clarity while infection instead shows infiltrate with discharge. Irreversible rejection re grafts.", ["Incorrect. Clarity is lost.", "Correct. Rejection, steroid rescue.", "Incorrect. No infiltrate pattern.", "Incorrect. Sutures irritate locally."], "Line on graft with red eye: reject rejection with steroids."),
  mcq("bk2-oph-038", "Nummular subepithelial infiltrates with glare months after red eye epidemic are sequelae of what?", ["Trachoma", "Adenoviral keratoconjunctivitis", "Gonococcus", "Vitamin A deficiency"], 1, "Adenovirus leaves immune stromal dots scattering light; lubricants and brief cautious steroids ease visually significant cases while reassuring resolution over months.", ["Incorrect. Trachoma scars lids.", "Correct. Adenoviral nummuli.", "Incorrect. Gonococcus melts acutely.", "Incorrect. Xerosis dries surface."], "Epidemic red eye then dots and glare: adenovirus."),
  mcq("bk2-oph-039", "Pseudomonas corneal ulcer in lens wearers is feared chiefly because what?", ["It itches", "Rapid stromal melting and perforation within hours needing admission", "It never heals", "Bilateral always"], 1, "Proteases liquefy collagen overnight with greenish mucopurulent discharge; hourly fortified therapy with admission and lens case culture controls damage. Delay perforates.", ["Incorrect. Pain dominates, not itch.", "Correct. Melts in hours.", "Incorrect. Treated early it heals.", "Incorrect. Usually unilateral."], "Lens ulcer melting overnight: Pseudomonas."),
  mcq("bk2-oph-040", "Steroids are contraindicated as solo therapy in which corneal infections?", ["Healed scars", "Active bacterial, fungal, acanthamoeba and herpetic epithelial disease", "Allergic conjunctivitis", "Dry eye"], 1, "Steroids blunt immunity letting organisms replicate while masking signs; they enter only with antimicrobial cover for stromal inflammation or graft rejection. Solo use perforates infected corneas.", ["Incorrect. Scars accept cautious steroids.", "Correct. Never solo in live infection.", "Incorrect. Allergy welcomes brief steroids.", "Incorrect. Dry eye uses mild steroids."], "Live corneal infection plus lone steroid equals perforation.")]);

add("oph-corneal-degenerations", "Corneal degenerations, dystrophies and ectasias", "corneal_degenerations_dystrophies_keratoconus", "Corneal Degenerations, Dystrophies and Ectasias",
 ["Keratoconus", "Fuchs dystrophy", "Arcus and band keratopathy", "Pterygium and degenerations"],
 [step("**Keratoconus** thins central cornea into a cone after puberty (bilateral but asymmetric, vernal allergy and Down syndrome with eye rubbing associations): progressive myopic astigmatism uncorrectable by glasses, scissors reflex on retinoscopy, Munson sign (lower lid bulge on downgaze), Vogt striae, Fleischer iron ring and apical scarring. Topography diagnoses early cones; **corneal crosslinking** halts progression, rigid gas permeable or scleral lenses rehabilitate vision, and acute hydrops (Descemet tear with sudden stromal oedema) needs hyperosmotics then DALK or penetrating graft for scars.", "Teen with worsening astigmatism glasses cannot fix: map the cornea. Cone plus iron ring is keratoconus; crosslink early."),
  step("Endothelial failure clouds mornings: **Fuchs dystrophy** (guttae, Descemet thickening, morning blur clearing later) progresses to bullous keratopathy with painful ruptured bullae, treated by hypertonic saline, bandage lenses and endothelial keratoplasty (DSEK or DMEK). **Pseudophakic bullous keratopathy** follows complicated cataract surgery similarly. **Arcus senilis** (peripheral lipid ring with clear interval) is ageing physiology, but arcus before forty hunts hyperlipidaemia; **band keratopathy** calcifies interpalpebral Bowman in chronic uveitis or hypercalcaemia, removed by chelation (EDTA).", "Morning blur clearing by noon is Fuchs endothelium failing. Arcus young means lipids; band calcium means chronic uveitis or calcium excess."),
  step("Stromal dystrophies deposit bilaterally and symmetrically: granular (bread crumb deposits), macular (cloudy with Descemet involvement, autosomal recessive), lattice (refractile lines with recurrent erosions and amyloid). **Salzmann nodular degeneration** raises bluish nodules after chronic surface disease. **Terrien marginal degeneration** thins superior periphery with against the rule astigmatism. Keratoglobus balloons the whole cornea from birth (brittle, rupture prone). Phototherapeutic keratectomy smooths superficial dystrophies; deeper disease grafts.", "Bilateral symmetric deposits are dystrophies; lattice lines bleed into erosions. Nodular Salzmann follows chronic surface inflammation."),
  step("Limbal stem cell failure (chemical burns, Stevens Johnson, aniridia) conjunctivalises cornea with vessels and persistent defects, needing amniotic membrane or stem cell transplantation rather than standard grafts which fail. **Pterygium** recurrence prevention uses conjunctival autografting; bare sclera techniques recur. Corneal tattooing and prosthetic (keratoprosthesis) options serve blind opaque corneas unsuitable for grafts. Kayser Fleischer rings (Descemet copper) flag Wilson disease in young patients with movement disorders, distinct from Fleischer iron rings of keratoconus.", "Vessels marching over cornea after burns means stem cells died: grafts fail without them. Copper ring plus tremor is Wilson.", tbl(["Ring", "Disease", "Metal"], [["Fleischer ring", "Keratoconus cone base", "Iron"], ["Kayser Fleischer ring", "Wilson disease", "Copper in Descemet"], ["Arcus", "Ageing or hyperlipidaemia", "Lipid"], ["Band keratopathy", "Chronic uveitis", "Calcium"]]))],
 ["Glasses failing teen astigmatism: topography", "Morning blur clearing is endothelial", "Symmetric bilateral deposits are dystrophies", "Iron ring cone, copper ring Wilson"],
 "Biomechanical stromal weakening lets intraocular pressure steepen thin cones while endothelial pump failure swells stroma each night (lids closed, evaporation nil) clearing as day evaporates; dystrophic gene products precipitate layer by layer in Bowman, stroma or Descemet.",
 ["Keratoconus versus pellucid by cone position and crab claw", "Fuchs versus pseudophakic bullous by guttae and history", "Pterygium versus pinguecula by limbus crossing"],
 ["Corneal topography and pachymetry", "Specular microscopy for endothelial counts", "Systemic lipids, calcium and copper workup by ring"],
 [mcq("bk2-oph-041", "Scissors reflex on retinoscopy with irregular astigmatism in a teenager most suggests what?", ["Simple myopia", "Keratoconus needing topography and crosslinking assessment", "Cataract", "Glaucoma"], 1, "Irregular cone optics split the reflex; topography confirms and crosslinking stiffens progressive disease while spectacles fail. Allergic eye rubbing accelerates cones.", ["Incorrect. Myopia reflexes cleanly.", "Correct. Keratoconus cone.", "Incorrect. Lens opacifies, not distorts.", "Incorrect. Pressure spares reflex."], "Scissors reflex in teen: cone the cornea."),
  mcq("bk2-oph-042", "Munson sign in keratoconus refers to what?", ["Iron ring", "Lower lid bulge on downgaze from the cone", "Corneal clouding", "Lens dislocation"], 1, "The cone indents the lid in downgaze; Vogt striae and Fleischer rings complete bedside signs before topography quantifies. Acute hydrops instead clouds suddenly with pain.", ["Incorrect. Rings are Fleischer.", "Correct. Lid bulge on looking down.", "Incorrect. Transparency persists early.", "Incorrect. Lens sits posteriorly."], "Cone dents lid looking down: Munson."),
  mcq("bk2-oph-043", "Sudden painful corneal clouding with tearing in known keratoconus is which emergency?", ["Rejection", "Acute hydrops from Descemet tear needing hyperosmotics and later graft assessment", "Angle closure", "Endophthalmitis"], 1, "Descemet rupture floods stroma with aqueous; most settle over weeks leaving scars, with intracameral gas or keratoplasty for non resolving or scarred cases. Steroids alone never seal tears.", ["Incorrect. No graft exists to reject.", "Correct. Hydrops, dry then judge scar.", "Incorrect. Pressure signs differ.", "Incorrect. No intraocular pus."], "Cone suddenly milky and sore: hydrops tore Descemet."),
  mcq("bk2-oph-044", "Morning blurring clearing through the day with guttae in a 60 year old indicates what?", ["Keratoconus", "Fuchs endothelial dystrophy progressing to bullous keratopathy", "Cataract", "Macular degeneration"], 1, "Failing pumps swell stroma overnight; hypertonic drops temporise and endothelial keratoplasty restores when bullae rupture painfully. Cataract blurs constantly.", ["Incorrect. Cones distort youth.", "Correct. Fuchs morning oedema.", "Incorrect. Lens blur ignores time of day.", "Incorrect. Macula distorts centre constantly."], "Dawn blur fading by lunch: Fuchs endothelium."),
  mcq("bk2-oph-045", "Arcus senilis before age forty should prompt testing for what?", ["Wilson disease", "Hyperlipidaemia", "Diabetes always", "Hypothyroidism only"], 1, "Premature lipid keratopathy reflects systemic dyslipidaemia with vascular risk; senile arcus with lucid interval is otherwise benign ageing. Xanthelasma companions strengthen the hunt.", ["Incorrect. Wilson rings Descemet brown.", "Correct. Young arcus means lipids.", "Incorrect. Diabetes clouds lens.", "Incorrect. Thyroid swells orbits."], "Young arcus: bleed lipids."),
  mcq("bk2-oph-046", "Horizontal calcium band across interpalpebral cornea in chronic uveitis is what and removed how?", ["Arcus; statins", "Band keratopathy; EDTA chelation", "Dystrophy; graft at once", "Pterygium; excise"], 1, "Calcium deposits in Bowman membrane with lucid interval near limbus; chelation lifts it improving vision and comfort while uveitis control prevents return. Phosphate drops precipitate it.", ["Incorrect. Arcus is lipid periphery.", "Correct. Band calcium, chelate it.", "Incorrect. Dystrophies deposit symmetrically.", "Incorrect. No wing crosses limbus."], "Chalk band in chronic uveitis: chelate calcium."),
  mcq("bk2-oph-047", "Lattice dystrophy is distinguished by which features?", ["No erosions ever", "Refractile branching lines with recurrent painful erosions and amyloid deposits", "Unilateral always", "Pigment rings"], 1, "Amyloid lines fracture epithelium causing waking pain and erosions; hypertonics and bandage lenses bridge, with transplant for scarring. Granular dystrophy instead crumbs without early erosions.", ["Incorrect. Erosions define lattice.", "Correct. Lines plus erosions.", "Incorrect. Dystrophies strike bilaterally.", "Incorrect. Pigment rings are metabolic."], "Branching lines plus waking pain: lattice."),
  mcq("bk2-oph-048", "Kayser Fleischer ring differs from Fleischer ring by which pair?", ["Same lesion", "Copper in Descemet signalling Wilson disease versus iron at keratoconus cone base", "Both need graft", "Both are lipid"], 1, "Slit lamp separates brown Descemet copper in youth with hepatic or movement signs from rusty epithelial iron encircling cones; penicillamine pathways follow Wilson confirmation.", ["Incorrect. Metals and diseases differ.", "Correct. Copper Wilson, iron cone.", "Incorrect. Neither grafts primarily.", "Incorrect. Neither is lipid."], "Brown Descemet ring plus tremor: Wilson copper."),
  mcq("bk2-oph-049", "Corneal crosslinking is indicated to do what in keratoconus?", ["Restore lost vision fully", "Halt progression by stiffening stroma with riboflavin and ultraviolet light", "Replace endothelium", "Lower pressure"], 1, "Crosslinks freeze cone steepening in documented progressors (often youth); vision rehabilitation still needs contact lenses or later grafting for scars. Endothelium minimum thickness guards safety.", ["Incorrect. It freezes, not reverses.", "Correct. Stiffen to stop progression.", "Incorrect. Endothelium transplants separately.", "Incorrect. Pressure is glaucoma."], "Crosslink young cones to freeze them."),
  mcq("bk2-oph-050", "Limbal stem cell deficiency after chemical burns presents how and needs what?", ["Clear cornea; observe", "Conjunctivalisation with vessels and persistent defects needing stem cell or amniotic reconstruction", "Cataract; phaco", "High pressure; drops"], 1, "Destroyed palisades cannot resurface cornea so conjunctiva invades; standard grafts fail without stem support, requiring limbal transplantation before optical grafting.", ["Incorrect. Surface vascularises.", "Correct. Stem failure, transplant stems.", "Incorrect. Lens sits deeper.", "Incorrect. Pressure is separate."], "Burnt limbus grows conjunctiva: replace stems first.")]);

add("oph-sclera", "Diseases of the sclera", "scleritis_episcleritis_staphyloma", "Diseases of the Sclera",
 ["Episcleritis versus scleritis", "Necrotising scleritis", "Posterior scleritis", "Staphyloma and blue sclera"],
 [step("**Episcleritis** is benign sectoral redness with mild irritation in young adults (simple diffuse blanching, or nodular with a tender movable nodule), settling with lubricants or short NSAIDs and never threatening vision. **Anterior scleritis** burns deeply with severe tenderness, sleep waking pain, violaceous non blanching vessels and photophobia, often in rheumatoid or granulomatosis vasculitis; diffuse, nodular and necrotising variants ascend in danger. Phenylephrine blanches episcleral but not deep scleral vessels, separating them at the slit lamp.", "Mild red patch that blanches is episcleritis; deep boring pain that never blanches is scleritis."),
  step("**Necrotising scleritis** thins sclera toward perforation (with inflammation, red and exquisitely painful, or scleromalacia perforans without inflammation in rheumatoid hands), risking staphyloma and needing systemic steroids with steroid sparing immunosuppression plus rheumatology. Scleritis workup hunts connective tissue disease, ANCA vasculitis, tuberculosis, syphilis and gout with bloods and chest imaging; infectious scleritis follows surgery or trauma with purulent nodules needing debridement and fortified therapy. Scleral patch grafting tectonically supports impending perforation.", "Melting white wall with deep pain needs systemic immunosuppression, not drops alone. Quiet melt in rheumatoid is scleromalacia."),
  step("**Posterior scleritis** hides behind a white eye with vision loss, pain on eye movement, choroidal folds, disc swelling and exudative detachment, mimicking tumours or Harada disease; B scan shows the **T sign** (fluid in sub Tenon space) clinching diagnosis. Treatment is systemic NSAIDs or steroids with immunosuppression for necrotising or recurrent disease. Anterior uveitis, cataract and raised pressure complicate prolonged inflammation. Children and young adults get idiopathic or infectious patterns more often than vasculitic ones.", "White eye losing vision with pain on moving: scan for posterior scleritis T sign."),
  step("**Staphyloma** bulges thinned sclera lined with uvea: anterior (corneal scar with iris incarceration), intercalary (limbal), ciliary (ciliary body), equatorial and posterior (pathological myopia with macular degeneration and retinal risk). High myopia with posterior staphyloma needs retinal surveillance. **Blue sclera** shows choroid through thin collagen in osteogenesis imperfecta (with fractures and deafness), Ehlers Danlos and Marfan patterns; acquired thinning blues in scleromalacia and high myopia. Scleral buckling supports retinal detachment repair externally.", "Uveal lined bulge is staphyloma; blue plus fractures is brittle bone disease.", tbl(["Redness", "Pain", "Disease"], [["Sectoral mild", "Minimal", "Episcleritis"], ["Diffuse violaceous", "Severe boring", "Diffuse scleritis"], ["Nodule fixed deep", "Marked tender", "Nodular scleritis"], ["Pale thinning", "Quiet in RA", "Scleromalacia"]]))],
 ["Blanch test separates episclera from sclera", "Necrotising disease needs systemic drugs", "White eye with vision loss: posterior scleritis", "Blue sclera plus fractures: osteogenesis imperfecta"],
 "Immune complex vasculitis occludes deep episcleral plexuses, ischaemiating scleral collagen into necrosis, while posterior inflammation oozes into sub Tenon space outlining the T; collagen dysplasias thin sclera congenitally letting uveal pigment blue through.",
 ["Episcleritis versus scleritis by blanching and tenderness", "Necrotising with versus without inflammation by pain and redness", "Posterior scleritis versus tumour by T sign and systemic clues"],
 ["Phenylephrine blanching test at slit lamp", "Autoimmune, ANCA, infective and chest workup", "B scan for T sign in suspected posterior disease"],
 [mcq("bk2-oph-051", "Sectoral redness with mild irritation blanching fully with phenylephrine is what?", ["Scleritis", "Episcleritis needing only lubricants or brief NSAIDs", "Conjunctivitis always", "Uveitis"], 1, "Superficial vessels constrict while deep scleral plexus stays engorged in true scleritis; episcleritis never threatens vision and recurs benignly. Nodular variants ache more but still blanch.", ["Incorrect. Scleritis refuses blanching.", "Correct. Benign episcleritis.", "Incorrect. Conjunctivitis moves with conjunctiva.", "Incorrect. Uveitis cells the chamber."], "Blanches white with drops: episclera only."),
  mcq("bk2-oph-052", "Deep boring eye pain waking the patient with violaceous non blanching redness suggests what?", ["Dry eye", "Anterior scleritis needing systemic workup and therapy", "Stye", "Chalazion"], 1, "Severe tenderness with sleep disturbance marks scleral inflammation often tied to rheumatoid or vasculitis; topical steroids alone undertreat and perforation looms in necrotising forms.", ["Incorrect. Dry eye burns mildly.", "Correct. Scleritis, systemic hunt.", "Incorrect. Styes lump lids.", "Incorrect. Chalazia are painless."], "Boring pain that wakes: scleritis."),
  mcq("bk2-oph-053", "Painless scleral thinning with bluish hue in longstanding rheumatoid hands is what?", ["Active scleritis", "Scleromalacia perforans needing protection and immunosuppression despite quiet eye", "Episcleritis", "Pinguecula"], 1, "Necrotising without inflammation melts silently toward perforation with trivial trauma; shields, lubrication and rheumatology escalation with tectonic graft cover defects. Redness absence misleads.", ["Incorrect. Activity is absent here.", "Correct. Quiet melt, guard it.", "Incorrect. Episclera is red and benign.", "Incorrect. Pinguecula is conjunctival."], "Quiet blue melt in rheumatoid: guard against perforation."),
  mcq("bk2-oph-054", "B scan T sign in a painful eye losing vision with choroidal folds indicates what?", ["Retinoblastoma", "Posterior scleritis with sub Tenon fluid", "Detachment only", "Vitreous haemorrhage"], 1, "Fluid outlining globe and optic nerve forms a T; systemic anti inflammatories rescue vision while masquerading tumours undergo needless enucleation without scans.", ["Incorrect. Tumours calcify and grow.", "Correct. T sign, posterior scleritis.", "Incorrect. Detachment lacks T fluid pattern.", "Incorrect. Blood echoes mobiles differently."], "T of fluid behind globe: posterior scleritis."),
  mcq("bk2-oph-055", "Scleritis workup must hunt which systemic associations?", ["None needed", "Rheumatoid, ANCA vasculitis, tuberculosis, syphilis and gout", "Asthma only", "Migraine"], 1, "Near half of scleritis ties to systemic disease; serologies, chest imaging and rheumatology input change survival in vasculitis beyond the eye. Infectious cases follow trauma or surgery separately.", ["Incorrect. Associations kill systemically.", "Correct. Connective tissue and vasculitis hunt.", "Incorrect. Asthma is airway.", "Incorrect. Migraine aches differently."], "Scleritis means body wide vasculitis hunt."),
  mcq("bk2-oph-056", "Anterior staphyloma follows which sequence?", ["Congenital always", "Perforated corneal ulcer healing with iris incarceration bulging", "High pressure alone", "Cataract surgery"], 1, "Weak scar ectasia under pressure lines with uvea;tectonic grafting or evisceration pathways follow cosmesis and pain. Intercalary and ciliary variants follow limbal and ciliary injury.", ["Incorrect. Acquired ulcers dominate.", "Correct. Ulcer scar bulge with iris.", "Incorrect. Pressure alone rarely ectasias.", "Incorrect. Surgery wounds differ."], "Burst ulcer scar bulging with iris: staphyloma."),
  mcq("bk2-oph-057", "Child with blue sclera, repeated fractures and hearing loss most likely has what?", ["Battered baby only", "Osteogenesis imperfecta with thin collagen", "Rickets", "Scurvy"], 1, "Type I collagen defects blue the sclera, break bones and deafen (stapes); bisphosphonates, hearing aids and fracture care follow genetics. Non accidental injury lacks scleral and family pattern.", ["Incorrect. Sclera stays white in trauma.", "Correct. Brittle bones blue eyes.", "Incorrect. Rickets bows legs.", "Incorrect. Scurvy bleeds gums."], "Blue eyes plus broken bones: brittle collagen."),
  mcq("bk2-oph-058", "Posterior staphyloma in pathological myopia threatens sight through what?", ["Cataract only", "Macular degeneration, lacquer cracks and retinal detachment risk needing surveillance", "Glaucoma always", "Dry eye"], 1, "Ectatic posterior pole stretches retina into atrophy and holes; regular dilated exams with myopic maculopathy grading and detachment counselling preserve remaining vision.", ["Incorrect. Lens is separate.", "Correct. Stretched macula and detachments.", "Incorrect. Pressure is independent.", "Incorrect. Surface is anterior."], "Long eye bulging behind: watch macula and retina."),
  mcq("bk2-oph-059", "Infectious scleritis after pterygium surgery with purulent nodule needs what?", ["Steroids alone", "Debridement with fortified antibiotics and organism hunt", "Reassurance", "Patch only"], 1, "Pseudomonas and fungi seed bare sclera avascular beds; aggressive surgical sampling with intensive antimicrobials saves globe where steroids melt it. Rheumatology still excludes dual disease.", ["Incorrect. Steroids feed organisms.", "Correct. Cut and culture, fortify.", "Incorrect. Pus never reassures.", "Incorrect. Patch incubates."], "Pus on bare sclera post surgery: debride and fortify."),
  mcq("bk2-oph-060", "Nodular versus diffuse anterior scleritis differ in which bedside feature?", ["Colour only", "Fixed deep tender nodule versus widespread violaceous engorgement", "Vision always lost", "Age only"], 1, "Nodules fix to sclera resisting cotton bud movement unlike episcleritis; both ache deeply and need systemic therapy, nodular disease often heralding rheumatoid nodules elsewhere.", ["Incorrect. Depth and fixation differ.", "Correct. Nodule versus diffuse.", "Incorrect. Vision often preserved early.", "Incorrect. Ages overlap."], "Fixed deep nodule aching: nodular scleritis.")]);

add("oph-anterior-uveitis", "Anterior uveitis", null, null,
 ["Iritis and iridocyclitis", "Hypopyon uveitis", "HLA-B27 disease", "Steroid and mydriatic treatment"],
 [step("**Acute anterior uveitis** strikes one red painful photophobic eye with circumcorneal injection, cells and flare in the anterior chamber, keratic precipitates on endothelium, miosis and low or high pressure. **Granulomatous** disease (sarcoid, TB, sympathetic ophthalmia) lays large mutton fat precipitates with iris nodules (Koeppe at pupil margin, Busacca in stroma), while **nongranulomatous** HLA-B27-associated attacks (ankylosing spondylitis, Reiter, IBD, psoriasis) shower fine precipitates with fibrin and hypopyon. Slit lamp grading of cells and flare stages severity and treatment response.", "Red painful eye with cells floating inside: anterior uveitis. Big greasy precipitates mean granulomatous."),
  step("Systemic hunt follows pattern: unilateral alternating attacks suggest seronegative spondyloarthropathy (sacroiliac imaging, HLA-B27); bilateral granulomatous disease seeks sarcoidosis (chest imaging, ACE), tuberculosis (Mantoux or interferon assay), syphilis serology and herpetic causes (raised pressure with iris atrophy). Fuchs heterochromic iridocyclitis (heterochromia, stellate precipitates, cataract and glaucoma without synechiae) and Posner Schlossman glaucomatocyclitic crises (recurrent pressure spikes with mild cells) are unilateral special patterns. Juvenile idiopathic arthritis causes silent chronic bilateral disease needing screening.", "Alternating red eyes with back pain: HLA-B27. Quiet white eyes in arthritic children still need screening."),
  step("Treatment pairs intensive **topical steroids** (prednisolone hourly in severe attacks, tapering by cells) with **cycloplegic mydriatics** (atropine or homatropine breaking and preventing posterior synechiae while easing ciliary spasm pain). Raised pressure gets aqueous suppressants; herpetic disease adds oral antivirals; systemic steroids or immunosuppression (methotrexate, azathioprine, biologics) control posterior involvement, bilateral or recurrent disease. Dark glasses, rest and compliance counselling bridge the painful weeks. Steroid responders and cataract complicate prolonged drops.", "Steroid drops plus dilating drops is the anterior uveitis pair. Dilatation stops iris sticking to lens."),
  step("Complications punish delay: posterior synechiae (iris stuck to lens, irregular pupil, seclusio and angle closure), peripheral anterior synechiae, complicated cataract, secondary glaucoma (inflammatory, steroid induced or synechial), cystoid macular oedema, hypotony with phthisis in burnt out ciliary shutdown, and band keratopathy in chronic childhood disease. **Endophthalmitis** (postoperative or post traumatic with pain, lid swelling, hypopyon and vitritis) is the emergency mimic needing intravitreal antibiotics and vitrectomy, never steroids alone. Sympathetic ophthalmia threatens the fellow eye after penetrating injury.", "Iris glued to lens plus rising pressure is synechial angle closure. Postoperative pus inside the eye is endophthalmitis: inject antibiotics.", tbl(["Finding", "Pattern", "Disease"], [["Fine precipitates, fibrin", "Acute nongranulomatous", "HLA-B27 attack"], ["Mutton fat, nodules", "Granulomatous", "Sarcoid or TB"], ["Heterochromia, no synechiae", "Chronic low grade", "Fuchs iridocyclitis"], ["Pressure spikes, mild cells", "Recurrent unilateral", "Posner Schlossman"]]))],
 ["Cells and flare define anterior uveitis", "Dilate every anterior uveitis", "Alternating attacks mean spondyloarthropathy", "Postoperative hypopyon means endophthalmitis"],
 "Immune complex and T cell assault on uveal antigens (or molecular mimicry with joint and gut antigens) breaches blood aqueous barrier, spilling protein (flare) and leukocytes (cells) that organise into synechiae and membranes; herpetic trabeculitis separately blocks outflow raising pressure.",
 ["Granulomatous versus nongranulomatous by precipitates", "Uveitis versus conjunctivitis by pain, photophobia and cells", "Endophthalmitis versus sterile inflammation by pain and vitritis"],
 ["Slit lamp cell and flare grading", "HLA-B27, sacroiliac, chest, ACE, TB and syphilis workup", "B scan and vitreous tap in suspected endophthalmitis"],
 [mcq("bk2-oph-061", "Circumcorneal injection with cells and flare in the anterior chamber defines which diagnosis?", ["Conjunctivitis", "Acute anterior uveitis", "Episcleritis", "Dry eye"], 1, "Cells and protein leak mark intraocular inflammation with pain and photophobia; conjunctivitis keeps the chamber optically empty with discharge instead. Steroid and mydriatic therapy follows grading.", ["Incorrect. Conjunctiva discharges without cells.", "Correct. Anterior uveitis cells.", "Incorrect. Episclera reddens sectorally.", "Incorrect. Dry eye burns without cells."], "Cells swimming inside: uveitis, not pink eye."),
  mcq("bk2-oph-062", "Large mutton fat keratic precipitates with Koeppe and Busacca nodules indicate which type?", ["Nongranulomatous HLA-B27", "Granulomatous uveitis (sarcoid, TB patterns)", "Viral conjunctivitis", "Allergy"], 1, "Macrophage rich granulomas dot endothelium greasily with iris granulomas; sarcoid, tuberculosis and sympathetic ophthalmia lead differentials needing chest and infective workup.", ["Incorrect. B27 showers fine precipitates.", "Correct. Granulomatous disease.", "Incorrect. Conjunctiva lacks chamber cells.", "Incorrect. Allergy itches with papillae."], "Greasy big precipitates plus iris nodules: granulomatous."),
  mcq("bk2-oph-063", "Unilateral alternating acute anterior uveitis with back stiffness in a young man most suggests what?", ["Sarcoidosis", "HLA-B27 seronegative spondyloarthropathy (ankylosing spondylitis pattern)", "Behcet always", "Herpes simplex"], 1, "Alternating attacks with sacroiliitis, enthesitis or urethritis flag B27 disease; rheumatology co manages with NSAIDs and biologics while eyes get topical steroids. Bilateral granulomatous disease instead seeks sarcoid.", ["Incorrect. Sarcoid favours bilateral granulomas.", "Correct. B27 alternating attacks.", "Incorrect. Behcet adds mouth and genital ulcers.", "Incorrect. Herpes raises pressure with atrophy."], "Each eye in turn plus stiff back: B27."),
  mcq("bk2-oph-064", "Why are cycloplegic mydriatics mandatory in anterior uveitis?", ["Lower pressure only", "Prevent posterior synechiae and relieve ciliary spasm pain", "Dilate for cosmesis", "Treat infection"], 1, "Atropine or homatropine pulls iris from lens preventing seclusio and angle closure while paralysing the painful ciliary body; steroids alone leave adhesions forming. Dark glasses ease the dilated photophobia.", ["Incorrect. Some mydriatics raise pressure.", "Correct. Stop sticking, stop spasm.", "Incorrect. Cosmesis is irrelevant.", "Incorrect. Antimicrobials treat organisms."], "Dilate uveitis or iris glues to lens."),
  mcq("bk2-oph-065", "Fuchs heterochromic iridocyclitis is distinguished by which triad plus course?", ["Bilateral granulomas", "Heterochromia with stellate precipitates, cataract and glaucoma but no synechiae, chronic unilateral", "Hypopyon always", "Severe pain"], 1, "Low grade chronicity without adhesions confuses with quiet eyes; cataract surgery and glaucoma management dominate while steroids barely help. Rubella and CMV associations are studied.", ["Incorrect. Granulomas belong to sarcoid.", "Correct. Heterochromia, no synechiae.", "Incorrect. Hypopyon marks B27 flares.", "Incorrect. Pain is notably mild."], "Different coloured irises, quiet chronic cells: Fuchs."),
  mcq("bk2-oph-066", "Recurrent unilateral marked pressure spikes with mild anterior chamber cells is which entity?", ["Primary open angle glaucoma", "Posner Schlossman glaucomatocyclitic crisis", "Angle closure", "Pigmentary glaucoma"], 1, "Trabeculitis blocks outflow episodically with halos and mild inflammation settling between attacks; aqueous suppressants with brief steroids abort crises while herpetic testing excludes mimics.", ["Incorrect. POAG is bilateral and painless.", "Correct. Glaucomatocyclitic crisis.", "Incorrect. Closure shuts angles gonioscopically.", "Incorrect. Pigment storms follow exercise."], "Pressure storms with whisper of cells: Posner Schlossman."),
  mcq("bk2-oph-067", "Irregular pupil with 360 degree posterior synechiae and rising pressure after missed uveitis treatment is what?", ["Seclusio pupillae with iris bombe and secondary angle closure", "Simple mydriasis", "Third nerve palsy", "Pharmacologic dilation"], 1, "Iris bombe balloons forward blocking trabeculum; urgent steroids with mydriatics and pressure lowering precede laser iridotomy once inflammation cools. Prevention beats this emergency.", ["Correct. Seclusio bombe closes angle.", "Incorrect. Shape is irregular and fixed.", "Incorrect. Nerve palsies dilate regularly.", "Incorrect. Drops dilate roundly."], "Iris glued all round, ballooning forward: bombe."),
  mcq("bk2-oph-068", "Painful red eye with hypopyon and vitritis three days after cataract surgery is which emergency?", ["Expected inflammation", "Acute postoperative endophthalmitis needing intravitreal antibiotics and vitrectomy", "Allergy", "Dry eye"], 1, "Bacterial seeding (coagulase negative staph, streptococci) ferments inside with lid swelling and vision crash; vitreous tap with vancomycin and ceftazidime plus vitrectomy for severe cases saves eyes. Steroids alone blind.", ["Incorrect. Pain and vitritis exceed routine.", "Correct. Endophthalmitis, inject now.", "Incorrect. Allergy itches bilaterally.", "Incorrect. Surface dryness lacks pus."], "Postoperative pus inside eye: tap and inject."),
  mcq("bk2-oph-069", "Sympathetic ophthalmia threatens which eye after penetrating injury and needs what?", ["Injured eye only", "Fellow uninjured eye with granulomatous panuveitis; urgent immunosuppression with injury repair", "Neither eye", "Only the lens"], 1, "Exposed uveal antigens sensitise systemically, inflaming the sympathising eye weeks later with mutton fat precipitates and Dalen Fuchs nodules; high dose steroids and steroid sparing agents preserve bilateral vision.", ["Incorrect. Fellow eye is the victim.", "Correct. Spare eye inflames, suppress immunity.", "Incorrect. Both eyes at stake.", "Incorrect. Whole uvea inflames."], "One eye pierced, other eye inflames weeks later: sympathise fast."),
  mcq("bk2-oph-070", "Chronic silent bilateral anterior uveitis with band keratopathy in a girl with arthritis is typical of what?", ["HLA-B27 adult", "Juvenile idiopathic arthritis associated uveitis needing screening", "Trauma", "Herpes"], 1, "Oligoarticular JIA girls develop asymptomatic chamber cells scarring into cataract, glaucoma and band calcium; slit lamp screening every few months catches disease before synechiae. Pain absence delays presentation.", ["Incorrect. B27 aches acutely in adults.", "Correct. JIA silent uveitis, screen regularly.", "Incorrect. Trauma is unilateral.", "Incorrect. Herpes raises pressure."], "Arthritic girl, quiet eyes, band calcium: screen JIA.")]);

add("oph-posterior-uveitis", "Posterior uveitis, panuveitis and endophthalmitis", "posterior_uveitis_panuveitis", "Posterior Uveitis, Panuveitis and Endophthalmitis",
 ["Intermediate uveitis", "Toxoplasmosis and infections", "Behcet and VKH", "Endophthalmitis management"],
 [step("**Intermediate uveitis** (pars planitis) snows the inferior vitreous (snowballs) with snowbank exudates over pars plana in young adults, often idiopathic or with multiple sclerosis, sarcoid or Lyme associations; cystoid macular oedema blurs central vision. Periocular or systemic steroids with immunosuppression control persistent oedema, and pars plana vitrectomy clears debris in selected cases. Multiple sclerosis linkage mandates neurology review of white matter symptoms.", "Snowballs low in vitreous with swollen macula in young adult: intermediate uveitis. Ask about multiple sclerosis."),
  step("**Toxoplasmosis** causes the commonest infectious posterior uveitis: recurrent focal necrotising retinochoroiditis beside old pigmented scars (satellite lesions) with overlying vitritis (headlight in fog), from congenital or acquired Toxoplasma gondii. Active edges get pyrimethamine with sulfadiazine (folinic rescue) plus steroids, or trimethoprim sulfamethoxazole and azithromycin patterns; pregnancy and immunocompromise need specialist regimens. Cytomegalovirus retinitis (pizza pie haemorrhagic necrosis in AIDS with low CD4), acute retinal necrosis (herpetic peripheral whitening) and ocular tuberculosis complete infectious patterns.", "Old scar with fresh fluffy edge in foggy vitreous: toxoplasmosis. Treat parasites before steroids."),
  step("Systemic vasculitic patterns: **Behcet disease** (oral plus genital ulcers with hypopyon uveitis and retinal vasculitis along silk route populations) needs aggressive immunosuppression with biologics to prevent blinding occlusions; **Vogt Koyanagi Harada disease** (bilateral exudative detachments with disc swelling, vitiligo, poliosis, meningismus after viral prodrome in pigmented races) needs prolonged high dose steroids with steroid sparing agents to prevent sunset glow fundus. Sympathetic ophthalmia and sarcoid panuveitis join bilateral granulomatous patterns. Fluorescein angiography maps vasculitis and ischaemia guiding laser.", "Mouth plus genital sores plus hypopyon: Behcet. Vitiligo plus bilateral detachments: VKH."),
  step("**Endophthalmitis** divides exogenous (postoperative acute within days, bleb related, post traumatic with Bacillus ferocity, endogenous septic emboli in diabetics or immunosuppressed with bilateral potential) from sterile inflammation by pain, vision crash, lid swelling, hypopyon and dense vitritis obscuring fundus. Vitreous tap with intravitreal vancomycin and ceftazidime (plus dexamethasone debates) starts immediately; early vitrectomy benefits severe postoperative cases. Prophylaxis is povidone iodine prep with intracameral antibiotics at cataract surgery. Sympathetic and toxic anterior segment syndromes mimic early but lack vitritis.", "Pain plus no fundus view after surgery or trauma: tap vitreous, inject antibiotics now.", tbl(["Pattern", "Disease", "Anchor"], [["Snowbanks inferior", "Intermediate uveitis", "Young adult, MS link"], ["Scar plus satellites", "Toxoplasmosis", "Headlight in fog"], ["Ulcers plus hypopyon", "Behcet", "Silk route"], ["Vitiligo plus detachments", "VKH", "Bilateral exudative"]]))],
 ["Snow in vitreous means intermediate disease", "Scar plus fresh edge means toxoplasmosis", "Behcet needs ulcers in two places plus eyes", "Endophthalmitis pain with no view: inject"],
 "Blood retinal barrier breakdown lets leukocytes and protein flood vitreous (haze and snowballs) while choroidal granulomas choke choriocapillaris into focal necrosis; Toxoplasma cysts rupture periodically reactivating edge retinitis beside old scars.",
 ["Intermediate versus posterior by vitreous versus retinal focus", "Toxoplasmosis versus CMV by immunity and scar pattern", "Endophthalmitis versus sterile uveitis by pain and vitritis"],
 ["Dilated fundus with vitreous grading", "Fluorescein angiography for vasculitis and ischaemia", "Vitreous tap with PCR and cultures in suspected infection"],
 [mcq("bk2-oph-071", "Snowballs and snowbanking over inferior pars plana with macular oedema in a 25 year old is what?", ["Anterior uveitis", "Intermediate uveitis (pars planitis)", "Central serous retinopathy", "Dry eye"], 1, "Vitreous centred inflammation with exudates characterises intermediate disease; MS, sarcoid and Lyme associations need review while steroids target oedema threatening reading vision.", ["Incorrect. Anterior disease cells the chamber.", "Correct. Intermediate snowbanks.", "Incorrect. Serous detaches macula without snow.", "Incorrect. Surface lacks vitritis."], "Snow low in vitreous: intermediate uveitis."),
  mcq("bk2-oph-072", "Focal retinal whitening beside an old pigmented scar with dense overlying vitritis is classic for what?", ["CMV retinitis", "Toxoplasmic retinochoroiditis", "Diabetic retinopathy", "Retinal detachment"], 1, "Satellite reactivation edges glow like headlights in fog; antiparasitics with steroids heal while steroids alone flare parasites. Congenital bilateral scars differ from acquired unifocal disease.", ["Incorrect. CMV lacks old scars, spreads haemorrhagic.", "Correct. Toxo scar satellites.", "Incorrect. Diabetes dots and blots bilaterally.", "Incorrect. Detachment corrugates without cells."], "Old scar with new fluffy neighbour: toxoplasmosis."),
  mcq("bk2-oph-073", "Pizza pie haemorrhagic retinal necrosis in advanced AIDS with CD4 under 50 indicates what?", ["Toxoplasmosis", "Cytomegalovirus retinitis needing systemic valganciclovir", "Herpes simplex", "Syphilis"], 1, "CMV creeps perivascularly with haemorrhage and granular edges toward zones threatening fovea and nerve; systemic therapy with immune restoration halts march while intravitreal bridges sight threatening lesions.", ["Incorrect. Toxo scars focally.", "Correct. CMV pizza pie in AIDS.", "Incorrect. Simplex necrotises acutely.", "Incorrect. Syphilis mimics variably."], "Haemorrhagic pizza in AIDS retina: CMV."),
  mcq("bk2-oph-074", "Oral plus genital ulcers with hypopyon uveitis and retinal vasculitis defines which disease?", ["VKH", "Behcet disease needing aggressive immunosuppression", "Sarcoidosis", "JIA"], 1, "Silk route vasculitis occludes retinal vessels blinding rapidly; pathergy, erythema nodosum and HLA-B51 support while biologics rescue refractory eyes. VKH instead vitiligos with detachments.", ["Incorrect. VKH detaches bilaterally.", "Correct. Behcet triple ulcer eye.", "Incorrect. Sarcoid granulomas differ.", "Incorrect. JIA is childhood joints."], "Two ulcer sites plus hypopyon: Behcet."),
  mcq("bk2-oph-075", "Bilateral exudative detachments with disc swelling, meningismus, vitiligo and poliosis after flu suggests what?", ["Behcet", "Vogt Koyanagi Harada disease needing prolonged steroids", "Central serous", "Harm"], 1, "Autoimmune melanocyte assault swells choroid detaching retina bilaterally; early high dose steroids with slow taper and steroid sparing agents prevent sunset glow depigmentation and chronicity.", ["Incorrect. Behcet ulcerates.", "Correct. VKH melanocyte storm.", "Incorrect. Serous is unilateral leak.", "Incorrect. Trauma is unilateral."], "Flu then white lashes plus bilateral detachments: VKH."),
  mcq("bk2-oph-076", "Post traumatic eye pain with hypopyon, ring infiltrate risk and fulminant course within hours suggests which organism pattern?", ["Staphylococcal mild", "Bacillus cereus fulminant endophthalmitis after soil contaminated injury", "Viral", "Sterile"], 1, "Bacillus toxins melt eyes within a day of farm injuries; emergent vitrectomy with intravitreal antibiotics offers the only salvage while prophylaxis starts at primary repair.", ["Incorrect. Staph smoulders slower.", "Correct. Bacillus lightning post soil.", "Incorrect. Viruses necrotise differently.", "Incorrect. Sterile lacks pus."], "Soil injury eye dead by morning: Bacillus."),
  mcq("bk2-oph-077", "Endogenous endophthalmitis with bilateral vitritis in a diabetic with Klebsiella liver abscess spreads by what route?", ["Direct trauma", "Haematogenous septic emboli needing blood cultures with systemic plus intravitreal therapy", "Allergy", "Surgery"], 1, "Bacteraemia seeds choroid bilaterally; source control (drain abscess), systemic antibiotics and ophthalmic injections run together while diabetes control aids. No wound exists.", ["Incorrect. No wound here.", "Correct. Blood borne seeding.", "Incorrect. Allergy lacks pus.", "Incorrect. No operation occurred."], "Liver abscess plus bilateral pus eyes: blood spread."),
  mcq("bk2-oph-078", "Acute retinal necrosis is distinguished by which features and needs what?", ["Slow bilateral drusen", "Herpetic peripheral confluent whitening with occlusive vasculitis needing high dose aciclovir plus steroids", "Only floaters", "No treatment"], 1, "Varicella and simplex necrotise periphery circumferentially toward fovea with vitritis; antivirals halt march while laser barricades detachments and fellow eye prophylaxis continues.", ["Incorrect. Drusen age slowly.", "Correct. Herpetic peripheral necrosis.", "Incorrect. Whitening defines it.", "Incorrect. Delay detaches."], "Peripheral retina whitening fast: herpetic necrosis."),
  mcq("bk2-oph-079", "Cystoid macular oedema as a complication of uveitis is best detected and treated how?", ["Tension check", "OCT petaloid leakage with periocular or systemic steroids and immunosuppression", "Patching", "Laser always"], 1, "OCT quantifies cystic thickening driving vision loss while angiography leaks petaloid; treating inflammation plus oedema (steroids, anti VEGF debates, vitrectomy selected) restores reading.", ["Incorrect. Pressure is separate.", "Correct. OCT oedema, suppress inflammation.", "Incorrect. Patching blinds amblyopes.", "Incorrect. Laser scars."], "Uveitic blur with petaloid leak: macular oedema."),
  mcq("bk2-oph-080", "Toxic anterior segment syndrome differs from endophthalmitis chiefly by what?", ["More pain", "Sterile postoperative inflammation within 24 hours with limbus to limbus oedema, no vitritis, from irrigant or instrument residue", "Later onset", "Vitreous pus"], 1, "TASS erupts same day from endotoxins or polishing compounds with wall to wall corneal oedema but quiet vitreous, settling with intensive steroids; endophthalmitis brews days later with vitritis needing antibiotics.", ["Incorrect. TASS pains less.", "Correct. Day one sterile wall oedema.", "Incorrect. TASS is earlier.", "Incorrect. Vitreous stays clear."], "Day one white wall, clear vitreous: toxic, not infective.")]);

add("oph-cataract", "Lens and cataract", "cataract_lens_surgery", "Lens and Cataract",
 ["Senile cataract types", "Congenital cataract", "Phaco and IOL surgery", "After cataract and complications"],
 [step("**Senile cataract** clouds with age by type: cortical (spoke opacities, glare, monocular polyopia), nuclear (brunescent browning with myopic shift improving near vision, second sight), posterior subcapsular (central plaque glaring in bright light, diabetics and steroid users), and hypermature Morgagnian (liquefied cortex with sinking nucleus, phacolytic glaucoma risk). Symptoms are painless blurring, glare, halos, frequent glass changes and fading colours. Maturation runs immature to mature to hypermature; intumescent lenses swell shutting angles.", "Glare plus frequent glass changes in elderly is cataract. Browning nucleus brings second sight before blindness."),
  step("**Congenital cataract** blinds amblyopically if missed: leukocoria with absent red reflex in newborn screening, unilateral (persistent hyperplastic primary vitreous, trauma) or bilateral (rubella with salt and pepper retinopathy and deafness, galactosaemia with oil drop cataract reversible by diet, Down syndrome, hypocalcaemia). Dense bilateral disease operates within weeks (lensectomy with vitrectomy in infants, IOL after age two debates), unilateral within days, followed by aggressive amblyopia patching and refraction. Rubella vaccination and galactose restriction prevent selected cases.", "White pupil in newborn is cataract until screened: operate dense bilateral within weeks. Rubella triad adds deafness and retinopathy."),
  step("Modern surgery is **phacoemulsification** with foldable intraocular lens: topical anaesthesia, small clear corneal incision, capsulorhexis, ultrasound sculpting with irrigation aspiration, in the bag IOL targeting emmetropia by biometry. Extracapsular extraction suits hard brown nuclei; intracapsular (cryo) belongs to subluxated lenses. IOL power formulas (SRK patterns) need axial length and keratometry; astigmatism managed by toric lenses or limbal relaxing incisions. Same day bilateral surgery stays selective for risk.", "Phaco with in bag lens through a small wound is the modern standard. Biometry picks lens power."),
  step("**Posterior capsular opacification (after cataract)** hazes months later (Elschnig pearls, fibrous membrane) and opens with Nd:YAG laser capsulotomy, not repeat surgery. Operative risks include posterior capsular rupture with vitreous loss, dropped nucleus, iris trauma, endophthalmitis (see uveitis wave), cystoid macular oedema (Irvine Gass), retinal detachment in myopes, and refractive surprise. Phacomorphic (swollen lens closing angle) and phacolytic (leaked protein clogging trabeculum with hypermature) glaucomas complicate neglected cataracts urgently.", "Blur months after good cataract surgery is after cataract: YAG it open. Swollen white lens with high pressure is phacomorphic.", tbl(["Cataract", "Clue", "Action"], [["Nuclear", "Brown, second sight", "Routine phaco"], ["Posterior subcapsular", "Glare, steroids or diabetes", "Early surgery"], ["Morgagnian", "Milky with sinking nucleus", "Beware phacolytic pressure"], ["Congenital dense", "Leukocoria newborn", "Operate weeks"]]))],
 ["Glare and glass changes mean cataract", "Newborn white pupil operates in weeks", "After cataract hazes later: YAG capsulotomy", "Swollen lens plus pressure is phacomorphic"],
 "Lens crystallins oxidise and aggregate with age, steroids and radiation while fibre NaK pumps fail, hydrating cortex into spokes; galactose pathway dulcitol swells infant fibres reversibly, and rubella arrests developing lens leaving nuclear dust.",
 ["Cortical versus nuclear versus subcapsular by glare and shift", "Congenital versus senile by red reflex and age", "Phacomorphic versus phacolytic by lens swelling versus leak"],
 ["Red reflex screening in newborns", "Slit lamp typing with dilated fundus for surgical planning", "Biometry with axial length and keratometry"],
 [mcq("bk2-oph-081", "Elderly patient reading better without glasses (second sight) with browning lens has which cataract?", ["Cortical", "Nuclear sclerotic with myopic shift", "Posterior subcapsular", "Congenital"], 1, "Nuclear compaction raises refractive index shorting focus; transient near gain precedes dense brunescent blindness needing phaco. Cortical disease instead glares with spokes.", ["Incorrect. Cortical spokes glare.", "Correct. Nuclear second sight.", "Incorrect. Subcapsular glares centrally.", "Incorrect. Congenital whitens newborns."], "New near vision in old brown lens: nuclear shift."),
  mcq("bk2-oph-082", "Diabetic on steroids with central glare worse in bright light most likely has which cataract?", ["Nuclear", "Posterior subcapsular", "Cortical peripheral", "Morgagnian"], 1, "Plaque at the nodal point scatters oncoming light; early surgery restores before density plus diabetes complicates macula. Steroid and radiation histories match.", ["Incorrect. Nuclear browns globally.", "Correct. Posterior subcapsular glare.", "Incorrect. Peripheral spokes spare centre early.", "Incorrect. Morgagnian liquefies totally."], "Bright light glare in steroid diabetic: posterior plaque."),
  mcq("bk2-oph-083", "Milky white lens with sinking brown nucleus inferiorly in neglected elderly eye is what and risk?", ["Mature safe", "Morgagnian hypermature with phacolytic glaucoma risk", "Congenital", "Traumatic"], 1, "Liquefied cortex leaks protein clogging trabeculum (phacolytic) while intact capsule mimics safety; urgent lens extraction with pressure control saves. Intumescent variants instead push iris closing angle.", ["Incorrect. Maturity here liquefies.", "Correct. Morgagnian, watch pressure.", "Incorrect. Age is senile.", "Incorrect. No injury history."], "Milky lens, sunken nucleus: Morgagnian leaks pressure."),
  mcq("bk2-oph-084", "Newborn with bilateral dense white cataracts should be operated when and followed by what?", ["Wait years", "Within weeks (lensectomy vitrectomy infants) then aggressive amblyopia patching and refraction", "Never operate", "Glasses only"], 1, "Visual deprivation amblyopia fixes within weeks; delayed surgery leaves permanent nystagmus and poor acuity despite clear media. Unilateral disease hurries even faster with contact lens rehabilitation.", ["Incorrect. Weeks decide vision.", "Correct. Early surgery plus patching.", "Incorrect. Blindness otherwise.", "Incorrect. Dense lenses block glasses."], "White pupils at birth: clear within weeks, patch for years."),
  mcq("bk2-oph-085", "Salt and pepper retinopathy with cataract and deafness in a newborn points to which cause?", ["Galactosaemia", "Congenital rubella needing vaccination prevention", "Down syndrome", "Trauma"], 1, "First trimester rubella scars lens, retina and cochlea with heart defects; MMR elimination campaigns prevent while galactosaemia instead oil drops reversibly with diet.", ["Incorrect. Galactose oil drops differ.", "Correct. Rubella triad.", "Incorrect. Down adds Brushfield spots.", "Incorrect. Trauma is unilateral."], "Cataract plus deafness plus retinopathy: rubella."),
  mcq("bk2-oph-086", "Oil drop cataract in an infant that reverses with diet restriction is characteristic of what?", ["Rubella", "Galactosaemia (galactokinase or transferase deficiency)", "Hypocalcaemia", "Steroids"], 1, "Dulcitol accumulation swells fibres reversibly early; lactose free diet clears lens while delay mental retards. Cataract plus developmental delay screens metabolism.", ["Incorrect. Rubella scars permanently.", "Correct. Galactose cataract, diet cures.", "Incorrect. Calcium causes lamellar dots.", "Incorrect. Infants lack steroid histories."], "Sweet urine plus reversible cataract: galactose."),
  mcq("bk2-oph-087", "Blur months after excellent cataract surgery with pearls behind the lens is what and treated how?", ["Endophthalmitis; inject", "Posterior capsular opacification; Nd:YAG capsulotomy", "Retinal detachment; buckle", "Glaucoma; drops"], 1, "Migrating equatorial cells pearl the posterior capsule (Elschnig) or fibrose it; laser opens a clear window in minutes without re entering the eye. Detachment instead flashes with curtain.", ["Incorrect. No pain or vitritis.", "Correct. After cataract, YAG it.", "Incorrect. No flashes or field cut.", "Incorrect. Pressure is normal."], "Good surgery gone hazy months later: YAG the capsule."),
  mcq("bk2-oph-088", "Swollen white lens with shallow chamber and acute high pressure in neglected cataract is which emergency?", ["Phacolytic", "Phacomorphic angle closure needing lens extraction with pressure control", "Open angle", "Neovascular"], 1, "Intumescent lens pushes iris forward closing trabeculum; mannitol and acetazolamide bridge to urgent extraction while laser iridotomy alone fails against lens bulk.", ["Incorrect. Phacolytic leaks, not swells.", "Correct. Phacomorphic lens bulk.", "Incorrect. Angles shut here.", "Incorrect. No new vessels."], "Fat lens shutting drain: extract the lens."),
  mcq("bk2-oph-089", "IOL power calculation chiefly needs which two measurements?", ["Corneal diameter only", "Axial length with keratometry (SRK patterns)", "Pressure and age", "Pupil size"], 1, "Biometry predicts effective lens position and vergence; errors surprise refraction postoperatively needing exchange or piggyback lenses. Toric planning adds axis mapping.", ["Incorrect. Diameter sizes anterior lenses.", "Correct. Length plus corneal curve.", "Incorrect. Pressure is glaucoma.", "Incorrect. Pupils size pharmacologically."], "Measure eye length and curve to pick lens."),
  mcq("bk2-oph-090", "Cystoid macular oedema after complicated cataract surgery (Irvine Gass) presents how and treated?", ["Painless high pressure", "Delayed central blur with petaloid leakage on OCT or angiography; topical NSAIDs with steroids", "Immediate blindness", "No treatment"], 1, "Inflammatory mediators cyst the macula weeks postoperatively, especially with vitreous loss; NSAIDs with steroids resolve most while chronic cases need periocular or anti VEGF escalation.", ["Incorrect. Pressure is separate.", "Correct. Irvine Gass oedema.", "Incorrect. Vision dips, not dies.", "Incorrect. Treatment works."], "Post cataract central blur weeks later: macular cysts.")]);

add("oph-glaucoma", "Primary glaucoma", "primary_glaucoma_open_closed", "Primary Glaucoma",
 ["Aqueous dynamics and angles", "Open angle glaucoma", "Angle closure emergency", "Drugs and surgery"],
 [step("Aqueous (ciliary processes) drains through trabecular meshwork and Schlemm canal; **open angles** fail at microscopic outflow while **closed angles** shut the drain by iris apposition. **Gonioscopy** grades Shaffer angles and spots plateau iris, pigment and neovascularisation; open angle management starts medically while narrow angles need laser iridotomy. Risk clusters: age, family, myopia in open angle, hypermetropia with short eyes in closure, steroids and trauma in secondary forms. Diurnal fluctuation and central corneal thickness correct pressure readings.", "Fluid made behind iris must leave through the angle. Look at the angle before treating pressure."),
  step("**Primary open angle glaucoma** silently excavates (increased cup disc ratio, notching, bayonetting, laminar dots, disc haemorrhages) with arcuate field loss (nasal steps, Bjerrum scotoma, ring scotoma, tunnel vision) sparing acuity until late. **Ocular hypertension** watches; **normal tension** glaucomas damage despite normal pressures needing lower targets. First line drops are **prostaglandin analogues** (latanoprost nocturnal, iris pigmentation and lash growth), then beta blockers (timolol, avoid asthma and bradycardia), alpha agonists (brimonidine), topical and systemic carbonic anhydrase inhibitors, and pilocarpine (miosis with brow ache). Selective laser trabeculoplasty increasingly leads therapy.", "Silent cupping with arcuate field cuts is open angle. Prostaglandin at night first, mind asthma with timolol."),
  step("**Acute angle closure** bursts with severe pain, halos, vomiting, mid dilated nonreactive pupil, hazy cornea and rock hard high pressure after dark or dilating drops in hypermetropic short eyes; fellow eye shares anatomy. Emergency lowers pressure with acetazolamide, mannitol, pilocarpine (once pressure permits iris response) and topical suppressants, then **laser peripheral iridotomy** in both eyes definitively (plus lens extraction debates in crowded segments). Chronic closure creeps with synechial shut angles needing iridotomy with medical or surgical control. Plateau iris persists after iridotomy needing iridoplasty patterns.", "Pain plus halos plus rock hard eye is angle closure: drugs now, holes in both irides after. Always treat the fellow eye."),
  step("Surgery when drops and laser fail: **trabeculectomy** fistulises aqueous under a guarded flap with mitomycin, nursing a diffuse bleb (leak, blebitis and endophthalmitis vigilance lifelong); tube shunts (Ahmed, Baerveldt) drain refractory or neovascular disease; cyclodestructive procedures shrink production in blind painful eyes; minimally invasive stents suit mild to moderate combined with cataract surgery. Target pressures individualise by damage and life expectancy; progression tracked by disc imaging (OCT nerve fibre layer) with visual fields every visit pattern. Steroid responders and pigment dispersion need cause control.", "Failed drops and laser: make a guarded drain with lifelong bleb watch. Track nerve fibre layer with fields.", tbl(["Drug", "Action", "Caution"], [["Latanoprost", "Uveoscleral outflow up", "Darkens iris, grows lashes"], ["Timolol", "Aqueous production down", "Asthma, slow pulse"], ["Pilocarpine", "Trabecular pull open", "Brow ache, myopia"], ["Acetazolamide", "Systemic production down", "Tingling, stones"]]))],
 ["Look at the angle first", "Open angle is silent until tunnel", "Closure pain needs drugs then bilateral iridotomy", "Prostaglandin first line, timolol avoids asthma"],
 "Trabecular endothelial phagocytosis fails with age and pigment clogging juxtacanalicular meshwork while pupillary block bows iris forward sealing the angle; chronic ischaemia and mechanical axonal compression at lamina cribrosa kill ganglion cells arcuate bundle by bundle.",
 ["Open versus closed angle by gonioscopy", "Glaucoma versus cataract by disc and fields versus lens", "Acute closure versus uveitis by pressure and pupil"],
 ["Tonometry with pachymetry correction", "Gonioscopy for angle grading", "Disc OCT with visual field mapping"],
 [mcq("bk2-oph-091", "Painless progressive arcuate field loss with cupped disc and open angles is which disease?", ["Angle closure", "Primary open angle glaucoma", "Cataract", "Macular degeneration"], 1, "Chronic outflow failure excavates silently; prostaglandin led therapy with target pressures preserves remaining nerve while fields monitor. Cataract instead glares with cloudy lens.", ["Incorrect. Closure pains acutely.", "Correct. Open angle silent cupping.", "Incorrect. Lens clouds visibly.", "Incorrect. Macula distorts centre early."], "Quiet tunnel vision with big cup: open angle."),
  mcq("bk2-oph-092", "First line medical therapy for primary open angle glaucoma is which class and caution?", ["Beta blocker always", "Prostaglandin analogue (latanoprost) at night; irreversible iris darkening and lash growth", "Pilocarpine first", "Oral steroids"], 1, "Once nightly dosing with strong efficacy leads guidelines; heterochromia and hypertrichosis counselled while asthma and bradycardia instead forbid timolol first. Laser trabeculoplasty rivals drops initially.", ["Incorrect. Timolol follows, minding lungs.", "Correct. Prostaglandin nights.", "Incorrect. Pilocarpine aches and myopes.", "Incorrect. Steroids raise pressure."], "Night drop darkening iris: prostaglandin first."),
  mcq("bk2-oph-093", "Severe eye pain with halos, vomiting, hazy cornea and mid dilated pupil after movie in dark indicates what?", ["Open angle", "Acute angle closure needing emergency pressure lowering then bilateral iridotomy", "Uveitis", "Migraine"], 1, "Darkness dilates pushing bulky iris over trabeculum in short hypermetropic eyes; acetazolamide, mannitol and pilocarpine bridge to definitive laser holes in both eyes. Migraine lacks rock hard globe.", ["Incorrect. Open angles never shut.", "Correct. Closure emergency.", "Incorrect. Uveitis constricts pupil.", "Incorrect. Migraine spares globe hardness."], "Dark room pain with halos: shut angle."),
  mcq("bk2-oph-094", "Definitive anatomical cure for pupillary block angle closure is what?", ["Lifetime pilocarpine", "Laser peripheral iridotomy (both eyes)", "Trabeculectomy first", "Cataract surgery never"], 1, "Iridotomy equalises chambers flattening iris from trabeculum; fellow eye prophylaxis prevents sequential blindness. Lenses extract in crowded or phacomorphic variants.", ["Incorrect. Drops bridge only.", "Correct. Holes in both irides.", "Incorrect. Filtration follows failed control.", "Incorrect. Lens removal helps crowded eyes."], "Block at pupil: hole the iris, both sides."),
  mcq("bk2-oph-095", "Timolol eye drops are contraindicated or cautioned in which patients?", ["Hypertensives", "Asthmatics and bradycardic or heart block patients", "Diabetics always", "Children only"], 1, "Systemic beta blockade wheezes and slows; ask lungs and pulse before prescribing while masking hypoglycaemia in brittle diabetics. Once daily gel preparations still absorb systemically.", ["Incorrect. Pressure patients benefit.", "Correct. Lungs and slow hearts beware.", "Incorrect. Diabetes cautions, not forbids.", "Incorrect. Ages all absorb."], "Wheezy slow pulse: skip timolol."),
  mcq("bk2-oph-096", "Nasal step on visual fields in glaucoma represents what?", ["Lens opacity", "Arcuate bundle defect respecting horizontal midline from nerve fibre loss", "Macular hole", "Cataract glare"], 1, "Superior and inferior arcuate fibres die first sparing midline; Bjerrum and ring scotomas extend the same bundle logic toward tunnel vision. Neurological defects instead respect vertical meridian.", ["Incorrect. Media clouds diffusely.", "Correct. Bundle step at midline.", "Incorrect. Macula holes centre.", "Incorrect. Cataract scatters."], "Step at nasal midline: arcuate fibres dying."),
  mcq("bk2-oph-097", "Trabeculectomy bleb with late redness, pain and vision drop after years suggests what?", ["Healed success", "Bleb related endophthalmitis needing emergency antibiotics and vitrectomy assessment", "Allergy", "Dry eye"], 1, "Thin avascular blebs leak and seed streptococci years on; leaking blebs with cells need admission, tap and intensive therapy while prophylactic repair debates continue. Lifelong bleb vigilance counselled.", ["Incorrect. Red pain never heals.", "Correct. Bleb infection emergency.", "Incorrect. Allergy itches mildly.", "Incorrect. Dryness lacks pus."], "Old filter bleb gone red and sore: infected."),
  mcq("bk2-oph-098", "Normal tension glaucoma differs from primary open angle chiefly by what management?", ["No treatment", "Damage despite normal pressures needing even lower targets with vascular workup", "Angle surgery always", "Steroids"], 1, "Disc haemorrhages and vascular dysregulation (migraine, Raynaud, sleep apnoea) accompany; pressure still lowers (drops, laser, surgery) toward single digits or low teens. Progression monitored identically.", ["Incorrect. Treatment still lowers.", "Correct. Normal pressure, lower target.", "Incorrect. Angles stand open.", "Incorrect. Steroids worsen."], "Cupping at normal pressure: aim lower still."),
  mcq("bk2-oph-099", "Pilocarpine relieves angle closure by which mechanism and limits use how?", ["Dilates pupil", "Miosis pulling iris from angle with brow ache, myopia and retinal detachment caution", "Dissolves lens", "Numbs eye"], 1, "Sphincter constriction thins peripheral iris opening trabeculum once pressure permits response; chronic use clouds lens and tugs retina in myopes. Definitive iridotomy follows.", ["Incorrect. Dilation shuts angles.", "Correct. Constriction opens, aches.", "Incorrect. Lens untouched.", "Incorrect. No anaesthesia."], "Pinpoint pupil opening drain but aching brow: pilocarpine."),
  mcq("bk2-oph-100", "Steroid induced glaucoma arises through which mechanism and needs what?", ["Angle closure", "Trabecular outflow resistance from steroid response; stop or switch steroids with pressure control", "Infection", "Retinal tear"], 1, "Responders (myopes, POAG families, children) clog meshwork within weeks of potent drops; scheduled pressure monitoring catches rises while fluorometholone or ciclosporin substitutes disease control.", ["Incorrect. Angles stay open.", "Correct. Steroid clogs drain.", "Incorrect. No organisms.", "Incorrect. Retina uninvolved."], "Drops raising pressure: steroid responder.")]);

